window.NIGHTS.cases[10]={"nr":10,"id":"case10","title":"Parzival","subtitle":"","level":"Finale","from":259,"to":284,"mythen":[],"sections":[{"id":"titel-und-pitch","kind":"intro","title":"Titel und Pitch","page":259,"layer":null,"blocks":10},{"id":"die-drei-akte","kind":"place","title":"DIE DREI AKTE","page":260,"layer":null,"blocks":5},{"id":"der-gral","kind":"place","title":"DER GRAL","page":260,"layer":null,"blocks":9},{"id":"der-fischerkoenig-und-parzival","kind":"place","title":"DER FISCHERKÖNIG UND PARZIVAL","page":261,"layer":null,"blocks":2},{"id":"der-gral-2","kind":"place","title":"DER GRAL","page":261,"layer":null,"blocks":9},{"id":"die-conditio-humana-der-zustand","kind":"place","title":"DIE CONDITIO HUMANA: DER ZUSTAND","page":262,"layer":null,"blocks":5},{"id":"selbstreflexion-entdeckung-des-geheimen-schmerzes","kind":"place","title":"SELBSTREFLEXION: ENTDECKUNG DES GEHEIMEN SCHMERZES","page":263,"layer":null,"blocks":6},{"id":"ein-verborgener-weg-heilung-der-existenziellen-wunde-durch-aufmerksamkeit","kind":"place","title":"EIN VERBORGENER WEG: HEILUNG DER EXISTENZIELLEN WUNDE DURCH AUFMERKSAMKEIT","page":263,"layer":null,"blocks":20},{"id":"sanfte-macht-der-zustand","kind":"place","title":"SANFTE MACHT: DER ZUSTAND","page":264,"layer":null,"blocks":6},{"id":"andere-heilen","kind":"place","title":"ANDERE HEILEN","page":264,"layer":null,"blocks":10},{"id":"aktivierung-des-grals","kind":"place","title":"AKTIVIERUNG DES GRALS","page":265,"layer":null,"blocks":6},{"id":"akt-1","kind":"layer","title":"AKT 1","page":265,"layer":null,"blocks":2},{"id":"die-erste-gralsritter-in","kind":"place","title":"DIE ERSTE GRALSRITTER:IN","page":265,"layer":"akt-1","blocks":22},{"id":"nachforschungen-ueber-corbin-payne","kind":"place","title":"NACHFORSCHUNGEN ÜBER CORBIN PAYNE","page":267,"layer":"akt-1","blocks":42},{"id":"nachforschungen-ueber-den-geheimen-schmerz","kind":"place","title":"NACHFORSCHUNGEN ÜBER DEN GEHEIMEN SCHMERZ","page":271,"layer":"akt-1","blocks":20},{"id":"der-heilende-monolog","kind":"place","title":"DER HEILENDE MONOLOG","page":272,"layer":"akt-1","blocks":16},{"id":"akt-2","kind":"layer","title":"AKT 2","page":272,"layer":null,"blocks":2},{"id":"die-zweite-gralsritter-in","kind":"place","title":"DIE ZWEITE GRALSRITTER:IN","page":272,"layer":"akt-2","blocks":75},{"id":"corbin-payne-hoechstpersoenlich","kind":"place","title":"CORBIN PAYNE HÖCHSTPERSÖNLICH","page":279,"layer":"akt-2","blocks":6},{"id":"erscheinungsbild","kind":"place","title":"ERSCHEINUNGSBILD","page":279,"layer":"akt-2","blocks":7},{"id":"kraefte","kind":"place","title":"KRÄFTE","page":279,"layer":"akt-2","blocks":13},{"id":"die-unterhaltung","kind":"place","title":"DIE UNTERHALTUNG","page":280,"layer":"akt-2","blocks":4},{"id":"der-gral-3","kind":"place","title":"DER GRAL","page":280,"layer":"akt-2","blocks":3},{"id":"nachforschungen-ueber-den-gral","kind":"place","title":"NACHFORSCHUNGEN ÜBER DEN GRAL","page":280,"layer":"akt-2","blocks":8},{"id":"akt-3","kind":"layer","title":"AKT 3","page":281,"layer":null,"blocks":7},{"id":"die-dritte-gralsritter-in","kind":"place","title":"DIE DRITTE GRALSRITTER:IN","page":281,"layer":"akt-3","blocks":5},{"id":"parkside-cafe","kind":"place","title":"PARKSIDE CAFE","page":281,"layer":"akt-3","blocks":13},{"id":"was-sein-muss","kind":"place","title":"WAS SEIN MUSS","page":282,"layer":"akt-3","blocks":6},{"id":"abwrackwerft","kind":"place","title":"ABWRACKWERFT","page":283,"layer":"akt-3","blocks":17}],"pages":{"259":{"tab":"","blocks":[{"t":"sh","x":"<b>DER ÜBERGREIFENDE FALL UM CORBIN PAYNE UND DIE</b>","sz":20.0,"box":[110.6,776.1,484.7,796.1],"p":259,"i":0,"sec":"titel-und-pitch"}],"size":[595.276,841.89]},"260":{"tab":"","blocks":[{"t":"p","x":"<i>Parzival</i> bildet die Rahmenhandlung der Kampagne. Der Fall erzählt nicht nur die Geschichte Corbin Paynes, sondern ist auch ein Streifzug durch den Schmerz selbst: den geheimen Schmerz der Protagonist:innen und den Weg zu seiner Heilung.","sz":13.0,"box":[53.9,63.6,284.3,163.6],"p":260,"i":0,"sec":"titel-und-pitch"},{"t":"p","x":"Der Fall und seine Handlung sind in drei Akte unterteilt, die jeweils nach einer Begegnung mit einem von Paynes Gralsritter:innen stattfinden und je ein neues Beweisstück enthüllen, das das Team zu Corbin Payne führt.","sz":9.5,"box":[53.9,174.1,281.0,233.6],"p":260,"i":1,"sec":"titel-und-pitch"},{"t":"p","x":"Während das Team <i>Parzival</i> spielt, ist es gezwungen, sich mit einigen Fragen auseinanderzusetzen, die den Kern der Stadt ausmachen: Was macht eine Schurk:in aus, warum ist jeder in der Stadt korrupt und was ist nötig, um diese Wunden zu heilen? Einige Mitglieder des Teams mögen Zyniker:innen sein, maskierte Rächer:innen auf der Suche nach Gerechtigkeit, doch dieser Fall fordert sie auf, sich der gewaltigen Aufgabe zu stellen, den Frieden in der Stadt wiederherzustellen – indem sie zuerst Frieden in sich selbst finden.","sz":9.5,"box":[53.9,242.3,284.1,364.3],"p":260,"i":2,"sec":"titel-und-pitch"},{"t":"p","x":"Der Hintergrund für diesen Fall, die Geschichte Corbin Paynes, findet sich unter Vergangenheit (s. S. 13). Zu Beginn der Kampagne stellt sich die Situation wie folgt dar:","sz":13.0,"box":[53.9,380.9,284.7,451.9],"p":260,"i":3,"sec":"titel-und-pitch"},{"t":"p","x":"<b>Corbin Payne</b> und <b>der Gral</b> sind dort, wo sie seit fast einem Jahrhundert sind: Payne sitzt im <u>Corbin Tower</u> (der Enklave der Gralsburg) und quält sich mit seinen legendären Schmerzen. Der Gral steht ihm zur Verfügung, aber er hat nicht die Mittel, ihn zu aktivieren. Obwohl der Turm im Herzen der Stadt liegt, können ihn nur die edelmütigsten Held:innen sehen oder finden. Sowohl die Magie der Enklave als auch der Nebel machen ihn unzugänglich.","sz":9.5,"box":[53.9,462.5,279.9,572.0],"p":260,"i":4,"sec":"titel-und-pitch"},{"t":"p","x":"<b>Dr. Krystal Knight</b>, verwundet durch ihre Scham, befindet sich in der <u>Anstalt</u> und gibt sich als Dr. Monahan aus, um die Stadt mit Hass auf Risse zu vergiften. Ihre Operation ist die <b>persönliche Ebene</b> (s. S. 20).","sz":9.5,"box":[53.9,580.6,285.9,627.8],"p":260,"i":5,"sec":"titel-und-pitch"},{"t":"p","x":"<b>Armand Kai</b>, verwundet durch seine Angst, hat sich in <u>Canseliet Manor</u> in der Altstadt eingesperrt, von wo aus er seine Riss-Ernte betreibt. Dies ist die <b>mystische Ebene</b> (s. S. 84).","sz":9.5,"box":[53.9,636.3,284.3,683.4],"p":260,"i":6,"sec":"titel-und-pitch"},{"t":"p","x":"<b>Vince Beaumont</b>, verwundet von seinem Kummer und von Zorn überwältigt, befindet sich in <u>Whitecliff,</u> das er in eine Enklave namens Albion verwandeln will, die als Ausgangspunkt für seinen Angriff auf die Stadt und den Fischerkönig dienen soll. Dies ist die <b>kriminelle Ebene</b> (s. S. 176).","sz":9.5,"box":[53.9,692.0,283.6,764.1],"p":260,"i":7,"sec":"titel-und-pitch"},{"t":"p","x":"<b>Rio Beaumont</b> (Parzival), verwundet durch Unwissenheit, ist eine alte Dame, die in Parkside, einem Stadtviertel nahe der Innenstadt, lebt. Im Gegensatz zu den anderen hat sie Zeit damit verbracht, ihren geheimen Schmerz und ihre Wunde zu heilen, um sich auf den Tag vorzubereiten, an dem sie den Gral wieder in Händen halten darf. Solange <b>Leugnet sie das Jenseitige</b> (<i>Spieler:innen-Handbuch</i>, S. 277) und ist Schläferin.","sz":9.5,"box":[309.0,64.5,539.8,161.5],"p":260,"i":8,"sec":"titel-und-pitch"},{"t":"h","x":"DIE DREI AKTE","sz":16.0,"box":[309.0,177.2,401.9,193.2],"p":260,"i":9,"skip":true,"sec":"die-drei-akte"},{"t":"p","x":"Jedes Mal, wenn das Team die Ermittlung in einer Ebene – der persönlichen, mystischen oder kriminellen – abschließt, trifft sie eine Gralsritter:in: Dr. Krystal Knight, Armand Kai oder Vince Beaumont (so ist die empfohlene Reihenfolge, aber du kannst sie nach Belieben ändern). Jede Gralsritter:in verrät ein wichtiges Detail, mit der der nächste Akt von <i>Parzival</i> beginnt.","sz":9.5,"box":[309.0,197.1,540.9,281.6],"p":260,"i":10,"sec":"die-drei-akte"},{"t":"p","x":"<b>AKT 1</b> beginnt, <b>wenn die erste Gralsritter:in die Existenz Corbin Paynes enthüllt</b>. Das spornt das Team an, dessen Geschichte zu finden <u>(Nachforschungen über Corbin Payne)</u> und seine Macht, zu korrumpieren, indem er den geheimen Schmerz nutzt, zu verstehen. <u>(Nachforschungen über den geheimen Schmerz).</u> Dies könnte einige SC dazu verleiten zu versuchen, ihren eigenen geheimen Schmerz zu heilen.","sz":9.5,"box":[309.0,290.3,539.5,387.3],"p":260,"i":11,"sec":"die-drei-akte"},{"t":"p","x":"<b>AKT 2</b> beginnt damit, <b>dass die zweite Gralsritter:in erklärt, wie man den Fischerkönig erreichen kann</b>. Das bringt das Team zu Paynes Versteck, <u>Corbin Tower.</u> Wenn es ihn nicht aufsucht, inszeniert Payne einen <u>Angriff auf die Stadt.</u> Diese Begegnung mit <u>Corbin Payne persönlich</u> dient als Weckruf. Payne könnte Mitglieder des Teams korrumpieren. Der Akt enthüllt <b>die Existenz des Grals</b>, was das Team veranlasst, <u>Nachforschungen über den Gral</u> anzustellen.","sz":9.5,"box":[309.0,395.9,541.1,505.4],"p":260,"i":12,"sec":"die-drei-akte"},{"t":"p","x":"<b>AKT 3</b> beginnt, <b>als die dritte Gralsritter:in das Team auf Rio aufmerksam macht</b>. Im unscheinbaren <u>Parkside Cafe</u> hat Rio alle Antworten den Gral und Payne betreffend. Gemeinsam mit ihr trifft das Team Payne wieder, nun auf der <u>Abwrackwerft,</u> dem einzigen Ort außerhalb des Turms, den Payne regelmäßig besucht, um zu angeln. Dort können die SC den verwundeten König und mit ihm die Stadt heilen. Wenn sie sich mit anderen Parteien zusammentun, um Payne gewaltsam ein Ende zu setzen <u>(Was sein muss),</u> verdammen sie die Stadt zu einem tiefen Schlaf.","sz":9.5,"box":[309.0,514.1,539.4,648.6],"p":260,"i":13,"sec":"die-drei-akte"},{"t":"h","x":"DER GRAL","sz":16.0,"box":[309.0,664.3,373.0,680.3],"p":260,"i":14,"skip":true,"sec":"der-gral"},{"t":"p","x":"Der Gral hat die Macht der universellen Gnade: Er kann jedes Unrecht wieder gutmachen, jede Wunde heilen und von Leid befreien. Er ist der Schlüssel zur Heilung Corbin Paynes und der Stadt. Deshalb befand er sich all die Jahre in seinem Besitz und wartete auf eine würdige Seele, die seine Kräfte der Güte freisetzt.","sz":9.5,"box":[309.0,684.2,537.0,756.2],"p":260,"i":15,"sec":"der-gral"}],"size":[595.276,841.89]},"261":{"tab":"","blocks":[{"t":"p","x":"Der Gral ist nur für würdige Nutzer:innen bestimmt, <b>die wissen, wer sie sind, verwundet waren und damit fertig geworden sind, und somit Corbin Payne widerstehen können</b>. Nur ein solcher Mensch kann den Gral zum Wohle aller nutzen. Als die junge, naive Rio Beaumont es versuchte, stürzte er sie in Verwirrung, da er lediglich ihre eigene Selbstüberschätzung widerspiegelte und ihr zeigte, dass sie nicht bereit war.","sz":9.5,"box":[53.9,59.9,284.7,156.9],"p":261,"i":0,"sec":"der-gral"},{"t":"p","x":"Um die Macht des Grals nutzen zu können, muss das Team jemanden kennen, der den Weg der Selbsterkenntnis gegangen ist und den eigenen geheimen Schmerz geheilt hat – oder ein SC muss diesen langen, beschwerlichen Weg gehen. Er ist unter <b>Heilung des geheimen Schmerzes</b> beschrieben (s. S. 262).","sz":9.5,"box":[53.9,165.6,283.6,237.7],"p":261,"i":1,"sec":"der-gral"},{"t":"h","x":"WARUM HABEN DIE GRALSRITTER:INNEN ALLE HINWEISE?","sz":14.0,"box":[65.2,257.5,255.4,285.5],"p":261,"i":2,"sec":"der-gral"},{"t":"p","x":"So wie die Bewohner:innen ihren schlimmsten Schmerz tief in sich begraben haben, hat der Nebel den schlimmsten Bürger, Corbin Payne, begraben. Nur die Gralsritter:innen erinnern sich an ihn oder an Details über ihn. Öffentlich zugängliches Wissen haben die Torwächter:innen (s. S. 76) und der Bibliothekar Fadi Malek (s. S. 267) weggesperrt.","sz":9.0,"box":[65.2,298.0,269.3,379.0],"p":261,"i":3,"sec":"der-gral"},{"t":"p","x":"Die Gralsritter:innen sind die einzigen, die in direkter Verbindung zu Payne stehen. Selbst ihre Lakai:innen kennen ihn nicht, höchstens als ominösen Spitznamen. Wenn das Team echte Hinweise will, muss es sie von einer Gralsritter:in bekommen.","sz":9.0,"box":[65.2,387.7,272.7,444.7],"p":261,"i":4,"sec":"der-gral"},{"t":"h","x":"PARZIVAL ALS EIGENSTÄNDIGER FALL","sz":14.0,"box":[65.2,489.2,240.2,503.2],"p":261,"i":5,"sec":"der-gral"},{"t":"p","x":"Obwohl dieser Fall als Rahmenhandlung konzipiert ist, kannst du die Ideen darin auch für einen eigenständigen Fall verwenden. Verwandle die Gralsritter:innen in Grenzgänger:innen-Risse, so dass man sie in je einer Szene besiegen kann, und Payne in eine Legende am Rande der Avatarschaft. Das Team muss ihn aufhalten, ehe er die Stadt seinem Schmerz unterwirft.","sz":9.0,"box":[65.2,515.7,266.5,608.7],"p":261,"i":6,"sec":"der-gral"},{"t":"h","x":"DER FISCHERKÖNIG UND PARZIVAL","sz":16.0,"box":[308.8,62.2,536.3,78.2],"p":261,"i":7,"skip":true,"sec":"der-fischerkoenig-und-parzival"},{"t":"p","x":"In der Sage vom Fischerkönig verwundet ein Fremder einen mächtigen König und verdammt ihn damit zu untätiger Trübsal, bis er nur noch fischen gehen kann. In der Folge verfallen sein Schloss und sein Reich. Parzival, ein naiver junger Mann, der reinen Herzens ist, findet das Schloss und entdeckt, dass der König den Gral (oder in einigen Versionen den Zauberkessel) besitzt, der alle Wunden heilen kann. Parzival will die Macht des Grals freisetzen, aber weil er ahnungslos und überfordert ist, verpasst er die Gelegenheit. Die Burg vergeht, und der König bleibt verwundet zurück. Von seinem Versagen gequält wandert Parzival jahrelang durch die Welt, auf der Suche nach der Gralsburg und einem tieferen Verständnis seiner selbst, bis er schließlich, als er einer zweiten Chance würdig ist, mit der Macht des Grals in Berührung kommt, um den Fischerkönig zu heilen und das Königreich wiederherzustellen.","sz":9.5,"box":[308.8,82.2,537.0,304.2],"p":261,"i":8,"sec":"der-fischerkoenig-und-parzival"},{"t":"h","x":"DER GRAL","sz":16.0,"box":[308.8,319.8,372.8,335.8],"p":261,"i":9,"skip":true,"sec":"der-gral-2"},{"t":"p","x":"Die Legende vom Gral und denen, die ihn suchen, ist eine Erzählung über die Rückkehr zu einem spirituellen Ursprung, dem Quell aller Dinge. Wenn die Heroen über alle Widrigkeiten siegen und sich mit etwas Tieferem in ihnen selbst verbinden, etwas, das alle Dinge miteinander vereint, ist das ungemein erholsam und heilt nicht nur sie selbst, sondern auch alle anderen.","sz":9.5,"box":[308.8,339.8,537.8,424.3],"p":261,"i":10,"sec":"der-gral-2"},{"t":"p","x":"Was ist diese Macht, an die der Gral appelliert? Das bleibt ein Rätsel. Vielleicht ist es ein anderer Mythos. Der Gral selbst ist einer. Er begann als Geschichte über einen magischen Kessel, mit dem man alles herstellen – und heilen – konnte. Aber vielleicht weist der Gral auf etwas hin, das jenseits des Reiches der Mythen liegt, ein Feld unendlicher Möglichkeiten und Freiheiten, die Quelle, aus der alle Mythen und alles Sein entspringen. Ein solcher Ort ist schwer zu begreifen. Nur Eingeweihte können seine weite, leere Stille erfassen. Wenn andere den Gral betrachten, sehen sie nur sich selbst und ihren Schmerz, der sich in ihm spiegelt.","sz":9.5,"box":[308.8,432.9,538.9,579.9],"p":261,"i":11,"sec":"der-gral-2"}],"size":[595.276,841.89]},"262":{"tab":"","blocks":[{"t":"p","x":"Der Eisberg","sz":30.0,"box":[79.4,42.1,205.2,72.1],"p":262,"i":0,"sec":"der-gral-2"},{"t":"h","x":"DEN GEHEIMEN SCHMERZ HEILEN","sz":23.0,"box":[309.0,63.4,478.3,114.4],"p":262,"i":1,"sec":"der-gral-2"},{"t":"p","x":"Um die Welt mit dem Gral zu heilen, muss man vorher sich selbst heilen.","sz":13.0,"box":[309.0,122.3,518.4,149.8],"p":262,"i":2,"sec":"der-gral-2"},{"t":"p","x":"Der Gral ist ein Gefäß für Aufmerksamkeit, und wenn er voll ist, ist er in der Lage, eine viel größere Quelle der Aufmerksamkeit anzuzapfen, die mächtiger ist und jenseits des Nebels, jenseits des Reiches der Mythen existiert. Wenn sich die Macht hinter dem Gral offenbart, ist sie absolut: Alles wird harmonisch und findet seinen Platz, und der Frieden ist wiederhergestellt.","sz":9.5,"box":[309.0,159.9,540.3,241.4],"p":262,"i":3,"sec":"der-gral-2"},{"t":"p","x":"<b>Das Problem ist, dass niemand, nicht mal Risse und Avatare, genug Aufmerksamkeit haben, um den Gral zu füllen.</b> Das liegt zum Teil am Nebel, der die Aufmerksamkeit der Menschen ablenkt und „stiehlt“, und zum Teil an den persönlichen geheimen Schmerzen der Menschen (die wiederum der Grund dafür sind, dass die Bewohner:innen der Stadt sich nach Ablenkung sehnen und sich dem Nebel so bereitwillig unterwerfen). De Mythen helfen beim Erwachen aus dem Nebel, verbrauchen aber einen Teil dieser Aufmerksamkeit. Da praktisch alle Bewohner:innen der Stadt die Aufmerksamkeit auf ihr Leben, ob gewöhnlich oder legendär, verschwenden, gibt es niemanden, der den Gral aktivieren kann, und das Leiden des Fischerkönigs und der Stadt geht weiter.","sz":9.5,"box":[309.0,249.6,541.2,427.0],"p":262,"i":4,"sec":"der-gral-2"},{"t":"p","x":"<b>Um sich des Grals würdig zu erweisen, muss ein SC seine eigene existenzielle Wunde, seinen geheimen Schmerz, finden, sich damit auseinandersetzen und sie heilen.</b> Dies kann nur gelingen, indem man ihr bewusst Aufmerksamkeit schenkt, oder anders ausgedrückt, dem Schmerz zuhört und kennenlernt.","sz":9.5,"box":[309.0,435.3,540.0,504.7],"p":262,"i":5,"sec":"der-gral-2"},{"t":"h","x":"DIE CONDITIO HUMANA: DER ZUSTAND","sz":16.0,"box":[309.0,520.4,466.7,553.4],"p":262,"i":6,"skip":true,"sec":"die-conditio-humana-der-zustand"},{"t":"p","x":"<b>Alle Bewohner:innen der Stadt sind verwundet</b> – das ist die unausgesprochene Wahrheit, die alle kennen und über die niemand spricht und der Grund, warum die Stadt so korrupt ist. Ob es die Existenz selbst ist, der Nebel, die Widerständigkeiten des Lebens, die Traumata der Vergangenheit, ein spukender Mythos oder alles zusammen, alle Bewohner:innen der Stadt tragen einen <b>geheimen Schmerz</b> in sich, auch die SC (<i>Spieler:innen-Handbuch</i>, S. 63).","sz":9.5,"box":[309.0,557.4,539.9,666.8],"p":262,"i":7,"sec":"die-conditio-humana-der-zustand"},{"t":"p","x":"<b>In <i>Parzival</i> kommt der geheime Schmerz der Bewohner:innen als ein Zustand ins Spiel</b>, den sie bisher hingenommen und ignoriert haben: Alle Bewohner:innen der Stadt sind <t>verwundet 6</t>. Diese Wunde tötet niemanden, aber sie definiert und diktiert das Handeln aller.","sz":9.5,"box":[309.0,675.6,540.0,747.5],"p":262,"i":8,"sec":"die-conditio-humana-der-zustand"}],"size":[595.276,841.89]},"263":{"tab":"","blocks":[{"t":"p","x":"Dieser Zustand wird zum ersten Mal enthüllt, wenn ein SC seine eigenen Beweggründe untersucht (s. u.) und entdeckt, dass auch ihn sein geheimer Schmerz treibt, und zwar schon immer. Er spiegelt nicht die vorübergehenden körperlichen und emotionalen Wunden des Charakters wider und ist auch nicht kumulativ. Nein, er beschreibt seine grundlegende, existenzielle Wunde.","sz":9.5,"box":[53.9,59.9,286.0,144.4],"p":263,"i":0,"sec":"die-conditio-humana-der-zustand"},{"t":"p","x":"<b>Diese Wunde (und ihr Zustand) ermöglicht es Corbin Payne, selbst die größten Held:innen zu verderben.</b> Als eine seiner Fähigkeiten kann Payne den Zustand <t>verwundet</t> in den Zustand <t>Nimmer heilende Wunde</t> umwandeln, wodurch er den Schmerz in einer Person sofort so verstärkt, dass sie zur Schurk:in wird.","sz":9.5,"box":[53.9,153.2,274.9,237.6],"p":263,"i":1,"sec":"die-conditio-humana-der-zustand"},{"t":"h","x":"SELBSTREFLEXION: ENTDECKUNG DES GEHEIMEN SCHMERZES","sz":16.0,"box":[53.9,253.3,276.5,286.3],"p":263,"i":2,"skip":true,"sec":"selbstreflexion-entdeckung-des-geheimen-schmerzes"},{"t":"p","x":"Eine Protagonist:in kann ihren eigenen Zustand <t>verwundet</t> entdecken, indem sie an einem beliebigen Punkt der Kampagne <b>Nachforschungen</b> über sich selbst anstellt. Der Charakter muss nicht explizit nach dem geheimen Schmerz suchen, jede Art von Gewissenserforschung oder Selbstreflexion ist eine Gelegenheit, diese Offenbarung einzuführen. Behandle dies wie eine reguläre Nachforschungen-Aktion. Ein SC kann eine Drehpause nutzen, um <i>an dem Fall zu arbeiten</i>, während er über sich selbst nachdenkt, oder einen Hinweis aus einer anderen relevanten Quelle ausgeben.","sz":9.5,"box":[53.9,290.2,285.5,437.2],"p":263,"i":3,"sec":"selbstreflexion-entdeckung-des-geheimen-schmerzes"},{"t":"p","x":"Das Motiv für diese Aktion führt Akt 1 der Geschichte ein, als das Team von Corbin Paynes Manipulation des geheimen Schmerzes erfährt, um Gralsritter:innen zu erschaffen <u>(Die erste Gralsritter:in,</u> S. 265). Dies führt zu <u>Nachforschungen über den geheimen Schmerz</u> (s. S. 262), die die Charaktere dazu anregen, <b>Nachforschungen</b> über ihre eigenen Motive anzustellen.","sz":9.5,"box":[53.9,445.9,282.6,530.5],"p":263,"i":4,"sec":"selbstreflexion-entdeckung-des-geheimen-schmerzes"},{"t":"p","x":"Wenn ein SC zum ersten Mal seinen geheimen Schmerz erforscht, frage die Spieler:in:","sz":9.5,"box":[53.9,539.0,248.9,561.0],"p":263,"i":5,"sec":"selbstreflexion-entdeckung-des-geheimen-schmerzes"},{"t":"sh","x":"<b>? WAS IST DEIN GEHEIMER SCHMERZ? IN- WIEFERN BEHERRSCHT ER DICH?</b>","sz":9.5,"box":[56.4,566.5,274.7,588.0],"p":263,"i":6,"sec":"selbstreflexion-entdeckung-des-geheimen-schmerzes"},{"t":"p","x":"(Beachte, dass ein SC nur <b>Nachforschungen</b> über seinen eigenen geheimen Schmerz anstellen kann. Ein SC darf den Zustand <t>verwundet</t> eines anderen nicht erfahren, bevor er seinen eigenen kennt).","sz":9.5,"box":[53.9,596.5,283.3,643.5],"p":263,"i":7,"sec":"selbstreflexion-entdeckung-des-geheimen-schmerzes"},{"t":"h","x":"EIN VERBORGENER WEG: HEILUNG DER EXISTENZIELLEN WUNDE DURCH AUFMERKSAMKEIT","sz":16.0,"box":[53.9,659.2,277.5,709.2],"p":263,"i":8,"skip":true,"sec":"ein-verborgener-weg-heilung-der-existenziellen-wunde-durch-aufmerksamkeit"},{"t":"p","x":"Sobald ein SC seinen Zustand <t>verwundet</t> entdeckt, kann er überlegen, wie er ihn heilen kann, und dabei Folgendes entdecken:","sz":9.5,"box":[53.9,713.1,274.6,747.6],"p":263,"i":9,"sec":"ein-verborgener-weg-heilung-der-existenziellen-wunde-durch-aufmerksamkeit"},{"t":"card","x":"Der Schmerz, den du leidest, ist tief verwurzelt. Es tut weh, nur daran zu denken, aber solange du ihn unterdrückst, wird er dich beherrschen. Um ihn zu heilen, musst du Zeit mit dir selbst verbringen, nach innen schauen und ihm die Aufmerksamkeit schenken, die er braucht, um zu heilen.","sz":null,"k":"yellow","box":[309.3,54.1,541.7,150.6],"p":263,"i":10,"sec":"ein-verborgener-weg-heilung-der-existenziellen-wunde-durch-aufmerksamkeit"},{"t":"p","x":"Den geheimen Schmerz zu heilen, erfordert ein Opfer, nicht von etwas oder jemandem, sondern von Dingen, die ein SC mit seiner Aufmerksamkeit tun möchte.","sz":9.5,"box":[309.0,159.2,536.6,193.7],"p":263,"i":11,"sec":"ein-verborgener-weg-heilung-der-existenziellen-wunde-durch-aufmerksamkeit"},{"t":"p","x":"<b><t>Verwundet</t> kann nur durch Aufmerksamkeitspunkte verringert werden.</b> Um diesen Zustand zu verändern gibt es keine andere Methode. Aufmerksamkeit kann man auf folgende Weise generieren:","sz":9.5,"box":[309.0,202.5,538.2,249.4],"p":263,"i":12,"sec":"ein-verborgener-weg-heilung-der-existenziellen-wunde-durch-aufmerksamkeit"},{"t":"p","x":"• Sobald ein SC diesen Weg freigeschaltet hat, füge <b>Drehpausen</b> eine weitere Option hinzu: <i>Dem geheimen Schmerz Aufmerksamkeit schenken</i>, was 1 Aufmerksamkeit für diesen Zweck erzeugt. Wenn die Spieler:in diese Option wählt, teilt sie mit, wie sie dies tut, z. B. durch Meditation, Gespräche usw.","sz":9.5,"box":[309.0,260.9,539.2,332.9],"p":263,"i":13,"sec":"ein-verborgener-weg-heilung-der-existenziellen-wunde-durch-aufmerksamkeit"},{"t":"p","x":"• <b>Eine schwere Entscheidung treffen</b>, um etwas aufzugeben und die Heilung zu fördern (1 Aufmerksamkeit). Wenn der geheime Schmerz jemanden z. B. zur Gewalt treibt, sollte die Person, wenn Gewalt sinnvoll wäre, darauf verzichten.","sz":9.5,"box":[309.0,341.6,535.7,401.1],"p":263,"i":14,"sec":"ein-verborgener-weg-heilung-der-existenziellen-wunde-durch-aufmerksamkeit"},{"t":"p","x":"• <b>Wenn ein SC eine Verbesserung eines Themas erhält</b>, kann er diese in 3 Punkte Aufmerksamkeit umwandeln, um seine Wunde zu heilen.","sz":9.5,"box":[309.0,409.7,528.1,444.2],"p":263,"i":15,"sec":"ein-verborgener-weg-heilung-der-existenziellen-wunde-durch-aufmerksamkeit"},{"t":"p","x":"• <b>Wenn ein SC ein Thema ersetzt</b>, kann er jeden Entwicklungspunkt in 3 Punkte Aufmerksamkeit umwandeln, um seine Wunde zu heilen.","sz":9.5,"box":[309.0,452.9,521.9,487.4],"p":263,"i":16,"sec":"ein-verborgener-weg-heilung-der-existenziellen-wunde-durch-aufmerksamkeit"},{"t":"p","x":"• Ein SC kann <b>Jetzt reicht’s!</b> für Aufmerksamkeit nutzen: 1 Aufmerksamkeit, wenn er Bruch markiert, 2 Aufmerksamkeit, wenn er Bruch markiert und alle Stärken eines Themas verbrennt. Wurde ein Thema ersetzt, gelten die oberen Regeln für das Ersetzen eines Themas (auch wenn es durch Markieren von Bruch ersetzt wird). Wenn der Charakter das ultimative Opfer bringt und stirbt, erzeugt das Aufmerksamkeit, als ob er alle Themen auf einmal verloren hätte, mindestens 10. Da er sie jedoch nicht zur Heilung seiner eigenen Wunde verwenden darf, kann er sie zur Heilung der Wunden anderer einsetzen: Die Spieler:in verteilt die Aufmerksamkeit auf die SC, die der Charakter heilen möchte.","sz":9.5,"box":[309.0,496.1,541.1,668.1],"p":263,"i":17,"sec":"ein-verborgener-weg-heilung-der-existenziellen-wunde-durch-aufmerksamkeit"},{"t":"p","x":"<b>Jeder so ausgegebene Punkt verringert <t>verwundet 6</t> um 1 Kästchen (oder Pip), beginnend von rechts.</b> Der erste Punkt reduziert den Zustand von Stufe 6 auf 5 mit vier angekreuzten Kästchen. Der Nächste reduziert ihn auf Stufe 5 mit drei Kästchen usw.","sz":9.5,"box":[309.0,679.7,539.5,739.1],"p":263,"i":18,"sec":"ein-verborgener-weg-heilung-der-existenziellen-wunde-durch-aufmerksamkeit"}],"size":[595.276,841.89]},"264":{"tab":"","blocks":[{"t":"p","x":"Verwundet","sz":11.0,"box":[109.8,103.7,181.8,114.7],"p":264,"i":0,"sec":"ein-verborgener-weg-heilung-der-existenziellen-wunde-durch-aufmerksamkeit"},{"t":"p","x":"Verwundet","sz":11.0,"box":[136.8,177.4,208.7,188.4],"p":264,"i":1,"sec":"ein-verborgener-weg-heilung-der-existenziellen-wunde-durch-aufmerksamkeit"},{"t":"p","x":"Verwundet","sz":11.0,"box":[162.3,251.7,234.3,262.7],"p":264,"i":2,"sec":"ein-verborgener-weg-heilung-der-existenziellen-wunde-durch-aufmerksamkeit"},{"t":"sh","x":"<b>ERZÄHLE, ODER ES IST NICHT PASSIERT</b>","sz":10.0,"box":[54.3,295.2,273.3,305.2],"p":264,"i":3,"sec":"ein-verborgener-weg-heilung-der-existenziellen-wunde-durch-aufmerksamkeit"},{"t":"p","x":"Immer wenn eine Spieler:in sich entscheidet, Aufmerksamkeit auszugeben, um den Zustand <t>verwundet</t> ihres Charakters zu heilen, stelle ihr eine Frage:","sz":9.5,"box":[53.9,310.8,277.8,345.3],"p":264,"i":4,"sec":"ein-verborgener-weg-heilung-der-existenziellen-wunde-durch-aufmerksamkeit"},{"t":"sh","x":"<b>? WELCHE ERKENNTNISSE HAST DU ÜBER DEINEN SCHMERZ GEWONNEN?</b>","sz":9.5,"box":[56.4,350.7,275.1,372.2],"p":264,"i":5,"sec":"ein-verborgener-weg-heilung-der-existenziellen-wunde-durch-aufmerksamkeit"},{"t":"sh","x":"<b>? WIE GEHST DU MIT DEINEM GEHEIMEN SCHMERZ UM?</b>","sz":9.5,"box":[56.4,377.6,271.0,399.1],"p":264,"i":6,"sec":"ein-verborgener-weg-heilung-der-existenziellen-wunde-durch-aufmerksamkeit"},{"t":"sh","x":"<b>? WIE KANNST DU DARAN ARBEITEN, DEI- NEN GEHEIMEN SCHMERZ LOSZULASSEN?</b>","sz":9.5,"box":[56.4,404.4,285.9,425.9],"p":264,"i":7,"sec":"ein-verborgener-weg-heilung-der-existenziellen-wunde-durch-aufmerksamkeit"},{"t":"p","x":"Heilung muss keine friedliche oder kathartische Erfahrung sein. Manchmal leidet der heilende Charakter während des Prozesses und kann verzweifeln, ermüden oder Frustration erleben, aber etwas in ihm verändert sich, und schließlich führt diese Veränderung zu einem größeren Verständnis.","sz":9.5,"box":[53.9,434.5,286.0,506.5],"p":264,"i":8,"sec":"ein-verborgener-weg-heilung-der-existenziellen-wunde-durch-aufmerksamkeit"},{"t":"h","x":"SANFTE MACHT: DER ZUSTAND","sz":16.0,"box":[53.9,522.1,161.2,555.1],"p":264,"i":9,"skip":true,"sec":"sanfte-macht-der-zustand"},{"t":"p","x":"Wenn ein Charakter zum ersten Mal ein Kästchen von <t>verwundet 6</t> heilt und ihn so auf Stufe 5 (mit 4 angekreuzten Kästchen) reduziert, erhält er den Zustand <t>geheilt 1</t>. Dieser bezieht sich auf die spezielle Heilung – die tiefgreifende Transformation des Wesens. Um Spannung zu halten, willst du <t>geheilt</t> vielleicht erst offenbaren, wenn er das erste Mal relevant wird.","sz":9.5,"box":[53.9,559.0,280.4,643.5],"p":264,"i":10,"sec":"sanfte-macht-der-zustand"},{"t":"p","x":"<b>Der Zustand <t>geheilt</t> ist ein Spiegelbild von <t>verwundet</t></b>, und seine Stufe ist immer 6 minus Stufe des Zustands <t>verwundet</t>. Man kann ihn durch keine andere Methode erhöhen oder verringern.","sz":9.5,"box":[53.9,652.3,271.8,699.2],"p":264,"i":11,"sec":"sanfte-macht-der-zustand"},{"t":"p","x":"Er verleiht dem Charakter die Fähigkeit, dem Fischerkönig zu widerstehen. Der SC kann <b>Sich der Gefahr</b> durch die <t>Nimmer heilende Wunde</t> mit dem Zustand <t>geheilt</t> als hilfreichem Zustand <b>stellen</b>. Er kann diesen Zustand nutzen, um <b>Sich der Gefahr zu stellen,</b> wenn","sz":9.5,"box":[53.9,707.9,285.8,767.5],"p":264,"i":12,"sec":"sanfte-macht-der-zustand"},{"t":"p","x":"jemand versucht, seinen Schmerz zu manipulieren, wie es die Gralsritter:innen oder Payne selbst tun werden.","sz":9.5,"box":[309.0,59.9,540.9,81.9],"p":264,"i":13,"sec":"sanfte-macht-der-zustand"},{"t":"p","x":"Schließlich verleiht <t>geheilt</t> dem Charakter eine größere Widerstandskraft gegen den Nebel, was ihm erlaubt, <b>Sich der Gefahr</b> gegen die Torwächter:innen <b>zu stellen,</b> wobei <t>geheilt</t> ein hilfreicher Zustand ist. Ein Charakter mit <t>geheilt 6</t> hat den Nebel transzendiert. Für ihn ist der Nebel ein weiterer Mythos, die Trennung von Nebel und Mythos ist aufgehoben, und alles Existierende ist eine verändernde Einheit.","sz":9.5,"box":[309.0,90.6,541.2,187.6],"p":264,"i":14,"sec":"sanfte-macht-der-zustand"},{"t":"h","x":"ANDERE HEILEN","sz":16.0,"box":[309.0,203.3,412.1,219.3],"p":264,"i":15,"skip":true,"sec":"andere-heilen"},{"t":"p","x":"Ein <t>geheilter</t> SC kann anderen helfen, sich von den verderblichen Auswirkungen der <t>Nimmer heilenden Wunde</t> zu erholen. Er kann dies tun, indem er ihnen zuhört oder seine Mythos-Kräfte auf eine aufmerksame Art und Weise einsetzt, die ihnen hilft, ihren geheimen Schmerz zu überwinden. Ein <t>geheilter</t> SC kann Momentum ausgeben (das er durch <b>Das Blatt wenden</b> oder auf andere Weise erzeugt hat), um die <t>Nimmer heilende Wunde</t> einer Gralsritter:in um eine Stufe zu verringern. Allerdings darf er die Stufe der <t>Nimmer heilenden Wunde</t> nicht unter die seines eigenen Zustands <t>Verwundet</t> senken. Die Gralsritter:in unterliegt weiterhin den Zwängen der <t>Nimmer heilende Wunde</t>, bis diese komplett entfernt ist, sie kann jedoch auf Stufe 4 oder darunter versuchen, Aktionen auszuführen, die ihm entgegenwirken (wobei die <t>Nimmer heilende Wunde</t> als Erschwernis wirkt).","sz":9.5,"box":[309.0,223.2,540.0,445.2],"p":264,"i":16,"sec":"andere-heilen"},{"t":"p","x":"Die geheilte Gralsritter:in behält ihren Zustand <t>verwundet</t> bei. Ein <t>geheilter</t> SC kann den Zustand <t>verwundet</t> eines anderen SC nicht verringern, aber erzählerisch helfen, indem er ihn auf denselben Weg führt.","sz":9.5,"box":[309.0,453.9,529.9,513.4],"p":264,"i":17,"sec":"andere-heilen"},{"t":"card","x":"DAS TIMING FÜR","sz":null,"k":"yellow","box":[295.8,521.6,495.4,544.9],"p":264,"i":18,"sec":"andere-heilen"},{"t":"p","x":"Die Heilung eines geheimen Schmerzes sollte sich gut anfühlen und sich über die <b>gesamte Kampagne</b> erstrecken. Andernfalls wird der SC zu früh <t>geheilt</t>, und Akt 3 würde seine cineastische Wirkung verlieren.","sz":9.5,"box":[309.0,548.9,536.4,595.9],"p":264,"i":19,"sec":"andere-heilen"},{"t":"p","x":"Wenn ein SC vor dem Ende von Akt 1 <t>verwundet 4</t> oder vor dem Ende von Akt 2 <t>verwundet 2</t> erreicht, kannst du ihm einen dramatischen Rückschlag verpassen.","sz":9.5,"box":[309.0,604.6,537.6,639.1],"p":264,"i":20,"sec":"andere-heilen"},{"t":"p","x":"Erzähle, wie die Heilung schwerer fällt und ihm mehr abverlangt, da <b>sein geheimer Schmerz sich wehrt.</b> Um dies widerzuspiegeln, erhöhe den Preis für die Heilung eines Kästchens <t>verwundet</t> auf 3 Aufmerksamkeitspunkte, eine Verbesserung (wenn die Aufmerksamkeitsleiste eines Themas voll ist) oder einen Entwicklungspunkt.","sz":9.5,"box":[309.0,647.8,532.9,732.3],"p":264,"i":21,"sec":"andere-heilen"}],"size":[595.276,841.89]},"265":{"tab":"","blocks":[{"t":"h","x":"EINE NEUE ART DER CHARAKTERENTWICKLUNG","sz":13.0,"box":[67.5,60.9,270.6,73.9],"p":265,"i":0,"sec":"andere-heilen"},{"t":"p","x":"Die Chance, den eigenen geheimen Schmerz zu heilen, stellt einen neuen Fortschritt dar, der sich nicht in einer größeren Mythos- oder Logos-Macht widerspiegelt, sondern in der inneren Transformation.","sz":9.0,"box":[67.5,86.7,272.5,131.7],"p":265,"i":1,"sec":"andere-heilen"},{"t":"p","x":"Wenn der Charakter von seinem geheimen Schmerz geheilt ist, <b>wird er selbst zu Parzival</b> und kann den Gral nutzen (s. u.) Wenn die Wunde des Charakters vollständig geheilt ist, <b>wird er zum Gral,</b> einem Gefäß voller Aufmerksamkeit, das in der Lage ist, eine mächtige Quelle anzuzapfen und Corbin Payne und die Stadt zu heilen.","sz":9.0,"box":[67.5,140.4,273.2,221.4],"p":265,"i":2,"sec":"andere-heilen"},{"t":"h","x":"AKTIVIERUNG DES GRALS","sz":16.0,"box":[53.9,257.1,220.6,273.1],"p":265,"i":3,"skip":true,"sec":"aktivierung-des-grals"},{"t":"p","x":"<b>Lass die Spieler während der gesamten Kampagne im Unklaren darüber, welche Stufe von <t>geheilt</t> erforderlich ist, um den Gral zu nutzen.</b> Lass sie theoretisieren, aber bestätige niemals eine ihrer Theorien. Nicht mal Rio könnte ihnen das sagen. Dieses Geheimnis bis zum Ende aufrechtzuerhalten macht das cineastische Finale noch viel spannender!","sz":9.5,"box":[53.9,277.2,284.1,361.5],"p":265,"i":4,"sec":"aktivierung-des-grals"},{"t":"p","x":"Wer noch <t>verwundet</t> ist und den Gral aktivieren will, sieht ein Spiegelbild seines geheimen Schmerzes darin und erhält <t>desorientiert</t> mit einer Stufe, die der seines Zustands <t>verwundet</t> entspricht. Bei <t>verwundet 6</t> könnte der Charakter dauerhaft mit <t>blind 6</t>, <t>taub 6</t>, <t>gelähmt 6</t> usw. belegt werden (ähnlich wie Payne durch seine Beschwörung). <b>Dies gilt vor allem im zweiten Akt, wenn die SC mit dem Gral in Berührung kommen.</b>","sz":9.5,"box":[53.9,370.2,284.1,467.3],"p":265,"i":5,"sec":"aktivierung-des-grals"},{"t":"p","x":"<b>Lass am Ende von Akt 3 cineastische Überlegungen den Ausgang des Spiels bestimmen.</b> Würfle nicht und verwende keine Regeln, um herauszufinden, ob der Charakter den Gral erfolgreich aktiviert. Dies sollte bereits aus der Geschichte und den Opfern während der Kampagne ersichtlich sein.","sz":9.5,"box":[53.9,476.0,285.6,547.9],"p":265,"i":6,"sec":"aktivierung-des-grals"},{"t":"p","x":"Der Gral lässt sich aktivieren durch:","sz":9.5,"box":[53.9,556.6,204.9,566.1],"p":265,"i":7,"sec":"aktivierung-des-grals"},{"t":"p","x":"• Einen engagierten SC, der sich selbst vollständig (<t>geheilt 6</t>) oder fast vollständig geheilt hat • Eine Gruppe von SC (und möglicherweise NSC), die ihre Aufmerksamkeit zusammenlegen, auch wenn sie einzeln nicht genug haben • Ein unumkehrbares Opfer eines SC, der <b>Jetzt reicht’s!</b> nutzt. • Rio Beaumont mit Unterstützung der SC • Eine unerwartete Gnade, die die Nöte, die die SC durchgemacht haben, würdigt","sz":9.5,"box":[53.9,571.9,277.7,693.9],"p":265,"i":8,"sec":"aktivierung-des-grals"},{"t":"h","x":"AKT 1","sz":23.0,"box":[309.0,63.4,363.3,86.4],"p":265,"i":9,"skip":true,"sec":"akt-1"},{"t":"p","x":"Akt 1 beginnt damit, dass das Team von Corbin Payne erfährt, dem rätselhaften „König in Karmesin“, der die Stadt nach Belieben vor Schmerz zucken lässt. Das Team macht sich daran, mehr über den Mann herauszufinden, und stößt auf die Quelle seiner Macht und die blutende existenzielle Wunde, die jeden in der Stadt in seine Gewalt bringt.","sz":13.0,"box":[309.0,94.3,540.1,223.3],"p":265,"i":10,"sec":"akt-1"},{"t":"h","x":"DIE ERSTE GRALSRITTER:IN","sz":16.0,"box":[334.8,241.9,515.5,257.9],"p":265,"i":11,"skip":true,"sec":"die-erste-gralsritter-in"},{"t":"p","x":"Am Ende der ersten Ebene <b>enthüllt die erste Gralsritter:in die Existenz Corbin Paynes</b>, was die SC dazu bringt, <u>Nachforschungen über Corbin Payne</u> anzustellen. Die Erforschung der Hintergründe einer Gralsritter:in kann die SC <u>Nachforschungen über den geheimen Schmerz</u> anstellen lassen, der den Kern des Leidens der Ritter:in und Verwandlung in eine Schurk:in bildet. Allerdings hat die Ritter:in keine Ahnung, wie man den Baulöwen finden (was Gralsritter:in 2 enthüllen wird) oder heilen kann (Gralsritter:in 3).","sz":9.5,"box":[309.0,261.8,541.3,383.8],"p":265,"i":12,"sec":"die-erste-gralsritter-in"},{"t":"sh","x":"<b>ÜBER CORBIN PAYNE</b>","sz":10.0,"box":[309.4,397.4,423.6,407.4],"p":265,"i":13,"sec":"die-erste-gralsritter-in"},{"t":"card","x":"<b>Ein König regiert diese Stadt.</b> Selbst die größten Legenden verneigen sich vor ihm, denn er ist der König der größten Mächte – des Leidens und der Qualen –, der jeden mit einem Fingerschnippen das Elend erleben lassen kann.","sz":null,"k":"yellow","box":[309.3,419.0,541.7,490.5],"p":265,"i":14,"sec":"die-erste-gralsritter-in"},{"t":"card","x":"<b>Durch ihn ist die Stadt, wie sie ist: korrupt und gewalttätig.</b> Die, die ihm begegnet sind, spüren seine Anwesenheit. Er dreht das Messer in der Wunde der Stadt um, kratzt am Schorf und treibt Menschen in den Wahnsinn.","sz":null,"k":"yellow","box":[309.3,499.7,541.7,570.8],"p":265,"i":15,"sec":"die-erste-gralsritter-in"},{"t":"card","x":"<b>Er heißt Corbin Payne</b>. Vor langer Zeit war er der Baulöwe, der diese Stadt aufgebaut hat.","sz":null,"k":"yellow","box":[309.3,580.0,541.7,614.0],"p":265,"i":16,"sec":"die-erste-gralsritter-in"},{"t":"sh","x":"<b>ÜBER PAYNES AUFENTHALTSORT</b>","sz":10.0,"box":[309.4,626.9,490.9,636.9],"p":265,"i":17,"sec":"die-erste-gralsritter-in"},{"t":"card","x":"<b>Niemand weiß, wo der König ist.</b> Die Legende besagt, er wohne in einem Turm am Meer, aber nur wenige haben ihn je gefunden, und wenn, finden sie ihn nie wieder.","sz":null,"k":"yellow","box":[309.3,648.0,541.7,706.8],"p":265,"i":18,"sec":"die-erste-gralsritter-in"}],"size":[595.276,841.89]},"266":{"tab":"","blocks":[{"t":"card","x":"<b>Die erste Gralsritter:in besuchte einst diesen Turm.</b> Deshalb darf sie nie wieder den Weg dorthin finden. • Payne hat Krystal Knight dorthin gebracht, als sich der Wolkenkratzer im Bau befand. • Armand Kai fand ihn bei der Suche nach dem Stein der Weisen • Beaumont entdeckte ihn bei der Suche nach Payne","sz":null,"k":"yellow","box":[54.1,54.1,286.6,181.2],"p":266,"i":0,"sec":"die-erste-gralsritter-in"},{"t":"sh","x":"<b>ÜBER IHRE BEZIEHUNG</b>","sz":10.0,"box":[54.3,193.9,181.7,203.9],"p":266,"i":1,"sec":"die-erste-gralsritter-in"},{"t":"card","x":"<b>Nachforschungen</b> über die Vergangenheit der Gralsritter:innen durch Gespräche, Retrokognition, Befragung von Toten oder das Finden alter Bilder <b>enthüllt die Hintergründe ihrer Beziehung zu Corbin Payne</b> (allerdings nur für die erste Ritter:in): • Krystal Knight war Corbin Paynes Therapeutin, bis er sie brach • Armand Kai suchte den Gral, aber Payne verschlimmerte seine Angst vor dem Tod • Beaumonts Tochter (Rio, <b>aber er kann sich nicht an ihren Namen erinnern</b>) ging zu Corbin Payne und verschwand, und die Trauer über ihren Verlust hat ihn mit Wut und Verzweiflung erfüllt Weitere Details über die gemeinsame Vergangenheit der Gralsritter:innen mit Corbin Payne findest du in den Hintergrundinformationen zu <i>Scherben</i> (Krystal Knight, S. 62), <i>Der Alchemist</i> (Armand Kai, S. 152) und <i>Albion erwache!</i> (Vince Beaumont, S. 182).","sz":null,"k":"yellow","box":[54.1,211.4,286.6,492.8],"p":266,"i":2,"sec":"die-erste-gralsritter-in"},{"t":"sh","x":"<b>ÜBER DIE NIMMER HEILENDE WUNDE</b>","sz":10.0,"box":[54.3,507.1,260.5,517.1],"p":266,"i":3,"sec":"die-erste-gralsritter-in"},{"t":"card","x":"Die Gralsritter:in steht unter einem schrecklichen, äußerst mächtigen Bann, der großes Leid zufügt, sie im Wahnsinn zur Gewalt treibt. <b>Der Bann scheint den innersten, essenziellen Schmerz anzuzapfen.</b>","sz":null,"k":"yellow","box":[54.1,525.9,286.6,597.0],"p":266,"i":4,"sec":"die-erste-gralsritter-in"},{"t":"h","x":"EINE LAUFENDE UNTERSUCHUNG","sz":14.0,"box":[65.0,628.9,216.1,642.9],"p":266,"i":5,"sec":"die-erste-gralsritter-in"},{"t":"p","x":"Das Team muss nicht alle Hinweise bei einer Begegnung oder an einem Schauplatz finden. Es kann frühere Hinweise bearbeiten, z. B. indem es sich erneut mit der Gralsritter:in trifft oder eine <b>Drehpause</b> damit verbringt, öffentliche Aufzeichnungen zu studieren.","sz":9.0,"box":[65.0,655.5,273.9,712.5],"p":266,"i":6,"sec":"die-erste-gralsritter-in"},{"t":"card","x":"<b>Jenseits des Nebels</b> scheinen die Gralsritter:innen von ihrem Mythos durchdrungen zu sein, stehen aber unter dem Einfluss eines anderen (dem des Fischerkönigs). Risse können folgendes zu sehen bekommen: • Die Gralsritter:in in rostiger Rüstung • Ein hinfälliger alter König auf seinem verrottenden Thron, der seine faltige Hand auf die Schulter der Ritter:in legt • Ein mittelalterlicher Speer oder eine Lanze, mit Juwelen verziert und doch düster, steckt im Herzen der Ritter:in • Der leuchtende Gral schwebt neben der Ritter:in • Im Hintergrund ein verfallener Turm am Meer, von dem die Betrachter:in glaubt, dass er einen dunklen Einfluss ausübt","sz":null,"k":"yellow","box":[309.6,54.1,542.0,296.4],"p":266,"i":7,"sec":"die-erste-gralsritter-in"},{"t":"card","x":"<b>Magische oder okkulte Forschungen können diese mystische Kraft als Nimmer heilende Wunde identifizieren</b>, eine legendäre Verletzung aus der Artussage.","sz":null,"k":"yellow","box":[309.6,305.6,542.0,364.6],"p":266,"i":8,"sec":"die-erste-gralsritter-in"},{"t":"card","x":"Wenn man die Punkte verbindet, kann man vermuten, <b>dass Corbin Payne die Quelle der Nimmer heilende Wunde ist</b>. Wenn er sie einer Person zugefügt hat, könnte er das auch bei vielen anderen getan haben.","sz":null,"k":"yellow","box":[309.6,373.5,542.0,445.0],"p":266,"i":9,"sec":"die-erste-gralsritter-in"},{"t":"h","x":"CORBIN TOWER IST UNERREICHBAR","sz":14.0,"box":[320.3,474.7,485.9,488.7],"p":266,"i":10,"sec":"die-erste-gralsritter-in"},{"t":"p","x":"Als Basis eines einflussreichen Avatars und Enklave der Gralsburg genießt Corbin Tower doppelte magische Tarnung durch den Nebel und Mythos-Kräfte der Avatar-Ebene, die undurchdringlich sind. Es ist nicht nötig, dies mit Regeln zu unterfüttern. Jeder Versuch, den Turm zu finden, der nicht durch erzählerische Umstände aussichtsreich erscheint, scheitert, und die Suchenden drehen sich im Kreis. Auch mit <b>Jetzt reicht’s!</b> können die Protagonist:innen den Wolkenkratzer nicht finden, obwohl sie je nach Opferstufe wertvolle Hinweise erhalten können.","sz":9.0,"box":[320.3,501.3,526.4,630.3],"p":266,"i":11,"sec":"die-erste-gralsritter-in"},{"t":"p","x":"Die, die wissen, dass der Turm existiert, sehen ihn manchmal zwischen den Wolkenkratzern in der Innenstadt, können das Gebäude aber nicht finden.","sz":9.0,"box":[320.3,638.9,522.4,671.9],"p":266,"i":12,"sec":"die-erste-gralsritter-in"},{"t":"p","x":"Um die Kampagne voranzutreiben, liegt der Schlüssel zur Suche nach Corbin Tower in den Händen der zweiten Gralsritter:in (s. S. 272).","sz":9.0,"box":[320.3,680.6,525.4,713.6],"p":266,"i":13,"sec":"die-erste-gralsritter-in"}],"size":[595.276,841.89]},"267":{"tab":"","blocks":[{"t":"h","x":"NACHFORSCHUNGEN ÜBER CORBIN PAYNE","sz":16.0,"box":[78.8,68.9,257.8,101.9],"p":267,"i":0,"skip":true,"sec":"nachforschungen-ueber-corbin-payne"},{"t":"p","x":"Wenn das Team über Corbin Payne in den frühen Tagen der Stadt recherchiert, bestehen dazu folgende Möglichkeiten:","sz":9.5,"box":[53.9,105.8,278.8,140.3],"p":267,"i":1,"sec":"nachforschungen-ueber-corbin-payne"},{"t":"p","x":"• In der Stadtbücherei in der Altstadt, wo die amtlichen Archive über Computer, Mikrofilmleser, Almanache, Gerichtsakten usw. zugänglich sind. • Durch Einsatz übersinnlicher Kräfte, wie z. B. das Blicken in die Vergangenheit oder Unterhaltungen mit den Geistern der Verstorbenen und eines Berichts aus erster Hand über die Vergangenheit • In der <u>Historischen Gesellschaft,</u> einer von den Torwächter:innen aufgestellten Falle für Risse, die zu tief graben (s. S. <i>Scherben</i>, S. 76)","sz":9.5,"box":[53.9,146.1,280.4,268.1],"p":267,"i":2,"sec":"nachforschungen-ueber-corbin-payne"},{"t":"p","x":"Sowohl in der Bücherei als auch auf der psychischen Ebene hat der sanftmütige Bibliothekar und Hüter des Wissens, der Riss <b>Fadi Malek</b> (Thoth, ägyptischer Gott des Wissens), alle Akten oder Visionen, die Payne betreffen, <t>magisch verschlüsselt 5</t>. Fadi weiß, dass Corbin Payne die, die ihn suchen, korrumpiert, weshalb er jeden hindert, Zugang zu finden. Das Team muss sich Malek gegenüber beweisen – oder ihn besiegen und die Dateien entschlüsseln –, ehe es das Wissen erhält. Malek weiß nicht, was in den Aufzeichnungen steht, er ist zu schlau, um sich damit zu befassen.","sz":9.5,"box":[53.9,274.0,284.8,408.5],"p":267,"i":3,"sec":"nachforschungen-ueber-corbin-payne"},{"t":"h","x":"DER KÖNIG IN KARMESIN","sz":14.0,"box":[65.2,441.5,183.4,455.5],"p":267,"i":4,"sec":"nachforschungen-ueber-corbin-payne"},{"t":"p","x":"Während auf der Straße praktisch niemand mehr den Namen Corbin Payne kennt, haben einige Veteran:innen und Informant:innen vielleicht von der Existenz eines „Monarchen“ gehört, der die Stadt regiert.","sz":9.0,"box":[65.2,468.1,275.0,513.1],"p":267,"i":5,"sec":"nachforschungen-ueber-corbin-payne"},{"t":"p","x":"Für die, die indirekt von Payne gehört haben, ist die Diskussion immer mit einem tief sitzenden Schrecken und einem starken Drang verbunden, seinen jeweiligen Rufnamen nicht auszusprechen. Wenn man sie drängt, werden sie ihn nennen. Je nachdem, wem sie begegnet sind, kennen sie den Monarchen als „Gottkönig“ (Armand Kais Magnum-Opus-Kult), „König in Karmesin“ (Beaumonts Bande) oder „Patient Null“ (Knights Heilung für die Gebrochenen).","sz":9.0,"box":[65.2,521.7,273.5,626.7],"p":267,"i":6,"sec":"nachforschungen-ueber-corbin-payne"},{"t":"p","x":"Wenn das Team bereits über Payne Bescheid weiß, bringt dies keine neuen Informationen. Es kann jedoch als Aufhänger für die nächste Ebene dienen, indem es auf die weist, die diesen Namen verwenden.","sz":9.0,"box":[65.2,635.4,274.0,680.4],"p":267,"i":7,"sec":"nachforschungen-ueber-corbin-payne"},{"t":"sh","x":"<b>DAS HERZ WIEGEN</b>","sz":10.0,"box":[309.4,62.8,411.8,72.8],"p":267,"i":8,"sec":"nachforschungen-ueber-corbin-payne"},{"t":"p","x":"Wer Zugang zum Wissen über die frühen Jahre der Stadt möchte, wird von Fadi Malek kontaktiert und über die Verschlüsselung informieren. Um das Wissen zu decodieren, lädt er das Team zur „<b>Herzenswägung</b>“ ein, dem ägyptischen Ritual, das die Seelen der Toten als würdig oder unwürdig für das Leben nach dem Tod einstuft. Er warnt das Team davor, die Prüfung ohne Vorbereitung zu wagen: Wer unwürdig ist, den verschlingt <b>die Göttin und Dämonin Ammit</b>.","sz":9.5,"box":[309.0,78.3,540.9,188.0],"p":267,"i":9,"sec":"nachforschungen-ueber-corbin-payne"},{"t":"p","x":"<b>Wenn das Team nicht auf die Prüfung vorbereitet ist</b>, wird Fadi Malek raten, „ihre Seelen zu erforschen und sich von ihrer Dunkelheit zu reinigen“. Sein Rat und die von ihm vorgeschlagene Lektüre könnten einige SC auf <u>Nachforschungen über den geheimen Schmerz</u> bringen. Fadi wird das Team einladen, sich der Prüfung im späteren Verlauf zu stellen.","sz":9.5,"box":[309.0,196.6,533.4,281.0],"p":267,"i":10,"sec":"nachforschungen-ueber-corbin-payne"},{"t":"p","x":"<b>Wenn die SC beschließen, das Ritual durchzuführen, findet es nachts in der Stadtbücherei statt.</b> Fadi Malek entnimmt magisch das Herz der Kandidat:in und wägt es gegen eine Feder ab. Wenn das Herz rein genug ist, ist es leichter als die Feder, und die Kandidat:in gilt als würdig. Andernfalls senkt sich die Waagschale mit dem Herzen, und Ammit kriecht aus dem Schatten. Du kannst das Ritual narrativ oder mit der Aktion <b>Ein Risiko eingehen</b> abhandeln, bei der nur Stärken im Zusammenhang mit Freundlichkeit, Mitgefühl und reine Absicht hilfreich sind. Hat der SC bereits einen Zustand <t>geheilt</t>, gilt dieser (s. S. 264). Wer keine Stärke oder Zustand hat, kann die Aktion nicht versuchen und gilt automatisch als unwürdig.","sz":9.5,"box":[309.0,289.8,540.4,461.7],"p":267,"i":11,"sec":"nachforschungen-ueber-corbin-payne"},{"t":"p","x":"Wenn mindestens ein Teammitglied für würdig befunden wird, entschlüsselt Fadi das Wissen. Unwürdige erhalten <t>markiert von Ammit 5</t>, ohne <b>Sich der Gefahr stellen</b> zu können. Nur Schicksals- und Seelenmanipulationskräfte können diesen Zustand aufheben. Dann taucht Ammit aus dem Dunkel zwischen den Bücherregalen auf und beginnt die Jagd.","sz":9.5,"box":[309.0,470.3,541.3,554.8],"p":267,"i":12,"sec":"nachforschungen-ueber-corbin-payne"},{"t":"p","x":"Der ideale Ansprechpartner ist der Schmuggler <b>Ben Pelican</b> (Henet, der Pelikan, der die Seelen im Jenseits bewacht), wenn er noch lebt und erwacht ist (s. S. <i>Der Alchemist</i>, S. 162).","sz":9.5,"box":[309.0,563.5,537.7,610.5],"p":267,"i":13,"sec":"nachforschungen-ueber-corbin-payne"}],"size":[595.276,841.89]},"268":{"tab":"","blocks":[],"size":[595.276,841.89]},"269":{"tab":"","blocks":[{"t":"sh","x":"<b>PAYNE VOR DEM FALL</b>","sz":10.0,"box":[54.3,62.8,173.7,72.8],"p":269,"i":0,"sec":"nachforschungen-ueber-corbin-payne"},{"t":"card","x":"Vor einem Jahrhundert war <b>Corbin Payne ein Bauunternehmer</b>, dessen Firma Payne Constructions mehr als die Hälfte der Häuser der Stadt baute. Sein Name war so sehr ein Synonym für die Stadt, <b>dass die Zeitungen sie damals „Payne Town“ nannten</b>.","sz":null,"k":"yellow","box":[54.1,77.5,286.6,161.3],"p":269,"i":1,"sec":"nachforschungen-ueber-corbin-payne"},{"t":"card","x":"<b>Er war Geschäftsmann, Philanthrop und Playboy.</b> Es gibt viele Zeitungsberichte über seinen Reichtum, den mondänen Lebensstil und seine beträchtlichen Spenden für wohltätige Zwecke. Zwar unterstellte man ihm Verbindungen zur Unterwelt, doch war es meist unbegründet. Payne unterhielt gute Beziehungen zur Stadtverwaltung und zur Polizei.","sz":null,"k":"yellow","box":[54.1,170.5,286.6,279.4],"p":269,"i":2,"sec":"nachforschungen-ueber-corbin-payne"},{"t":"card","x":"<b>Payne war ein Erfolgsmensch.</b> Er stammte aus einer Einwandererfamilie und wuchs in Cross End auf (als die Kirche Santa Teresa de Ávila noch aktiv war, s. <i>Dämon:innen in Cross End</i> in <i>Spielleitung 1x1</i>).","sz":null,"k":"yellow","box":[54.1,288.6,286.6,360.0],"p":269,"i":3,"sec":"nachforschungen-ueber-corbin-payne"},{"t":"card","x":"<b>Eine gründliche Recherche kann Fotos und Andenken zutage fördern, die den jungen Payne</b> als ein energiegeladenes und lebensfrohes Kind zeigen, das zu einem ungestümen und fleißigen Mann heranwuchs, mit einer „Erst arbeiten, dann feiern“-Mentalität.","sz":null,"k":"yellow","box":[54.1,368.9,286.6,452.7],"p":269,"i":4,"sec":"nachforschungen-ueber-corbin-payne"},{"t":"card","x":"Profiler:innen könnten die Theorie aufstellen, <b>dass im Leben des Mannes eine wachsende Leere herrschte</b>, die ihn dazu getrieben haben könnte, immerfort nach mehr zu streben, aber das bleibt Spekulation.","sz":null,"k":"yellow","box":[54.1,462.0,286.6,533.4],"p":269,"i":5,"sec":"nachforschungen-ueber-corbin-payne"},{"t":"sh","x":"<b>SCHÜSSE AUF DEM ROTEN TEPPICH</b>","sz":10.0,"box":[54.3,547.5,248.8,557.5],"p":269,"i":6,"sec":"nachforschungen-ueber-corbin-payne"},{"t":"card","x":"<b>Auf dem Höhepunkt seines Erfolgs schoss ein unbekannter Schütze, der nie gefasst wurde, Corbin Payne in den Bauch (manche sagen Leiste)</b>, als er auf dem Weg zu einer Wohltätigkeitsgala aus seiner Limousine ausstieg. <b>Er starb nicht, aber der Schuss hinterließ eine dauerhafte Behinderung.</b>","sz":null,"k":"yellow","box":[54.1,561.6,286.6,657.8],"p":269,"i":7,"sec":"nachforschungen-ueber-corbin-payne"},{"t":"card","x":"Die Untersuchung alter Fotos oder die Rückverfolgung der Schießerei zeigt, <b>dass der Schütze genauso aussah wie Corbin Payne</b>.","sz":null,"k":"yellow","box":[54.1,667.0,286.6,713.4],"p":269,"i":8,"sec":"nachforschungen-ueber-corbin-payne"},{"t":"card","x":"Das Ereignis ist <t>im Nebel der Zeit versunken 3</t>, aber arkane Praktiker:innen, die dies überwinden können (etwa Fadi Malek, falls das Team ihn rekrutiert), können entdecken, <b>dass der Schütze eine Beschwörung war, erschaffen durch Magie</b>. Ein weiterer Hinweis enthüllt, <b>dass Corbin Payne selbst die Beschwörung erschaffen hat</b>, was ihn als Riss identifiziert.","sz":null,"k":"yellow","box":[309.3,54.1,541.7,163.0],"p":269,"i":9,"sec":"nachforschungen-ueber-corbin-payne"},{"t":"sh","x":"<b>DER UNTERGANG</b>","sz":10.0,"box":[309.4,174.0,404.3,184.0],"p":269,"i":10,"sec":"nachforschungen-ueber-corbin-payne"},{"t":"card","x":"<b>Payne schloss sich in seinem Penthouse ein und ward nie mehr gesehen.</b> Seine Firma brach zusammen und wurde in zerschlagen. Zwei Jahrzehnte später fand man ihn tot auf, und seine wenigen verbliebenen Vermögenswerte wurden liquidiert, um die immensen Schulden zu begleichen.","sz":null,"k":"yellow","box":[309.3,190.7,541.7,286.8],"p":269,"i":11,"sec":"nachforschungen-ueber-corbin-payne"},{"t":"card","x":"<b>In der Sterbeurkunde steht, Payne sei an den Spätfolgen der Verwundung gestorben</b>, als Todesursache ist ein Blutgerinnsel angegeben. Das Studium der beigefügten Dokumente oder die Verwendung von Retrokognition zeigt, dass der Totenschein ohne Autopsie erstellt wurde. <b>Tatsächlich hat Corbin Payne kein Grab, und man hat nie seine Leiche gefunden.</b> Es scheint, als hätten Gläubiger das Rathaus unter Druck gesetzt, ihn für tot zu erklären. Eine andere Möglichkeit ist, dass der Nebel mit den Dokumenten seine Existenz verbirgt.","sz":null,"k":"yellow","box":[309.3,296.1,541.7,455.0],"p":269,"i":12,"sec":"nachforschungen-ueber-corbin-payne"},{"t":"sh","x":"<b>RESIDENZEN</b>","sz":10.0,"box":[309.4,468.1,379.8,478.1],"p":269,"i":13,"sec":"nachforschungen-ueber-corbin-payne"},{"t":"card","x":"Corbin Payne besaß mehrere Häuser in der Stadt und am Stadtrand, die laut Katasterunterlagen alle längst abgerissen wurden.","sz":null,"k":"yellow","box":[309.3,485.6,541.7,531.9],"p":269,"i":14,"sec":"nachforschungen-ueber-corbin-payne"},{"t":"card","x":"Nach den Schüssen auf ihn wurde Paynes größtes und megalomanischstes Bauprojekt, <b>ein Hochhaus namens <u>Corbin Tower</u></b>, gestoppt. Es gibt weder Aufzeichnungen über die Fertigstellung oder den Abriss noch Bau- oder architektonische Pläne.","sz":null,"k":"yellow","box":[309.3,541.2,541.7,625.0],"p":269,"i":15,"sec":"nachforschungen-ueber-corbin-payne"}],"size":[595.276,841.89]},"270":{"tab":"","blocks":[{"t":"threat","stars":"★★★★","name":"FADI MALEK","spectra":"","items":[],"box":[124.3,48.2,165.1,60.2],"p":270,"i":0,"sec":"nachforschungen-ueber-corbin-payne"},{"t":"p","x":"Fadi, der Riss einer mächtigen Wissensgottheit, ist schwer zu täuschen. Nur der hinterhältigste Riss kommt unbemerkt an ihm vorbei. In Menschengestalt kann er sich nicht besonders wehren, wird es aber versuchen. Wenn man ihn schwer verletzt, aktiviert er seine widerstandsfähigere Riesenpaviangestalt.","sz":9.0,"box":[62.4,71.4,277.6,140.4],"p":270,"i":1,"sec":"nachforschungen-ueber-corbin-payne"},{"t":"sh","x":"<b>VERLETZEN ODER UNSCHÄDLICH MACHEN 3 / SINNE ODER GEIST BEEINFLUSSEN –</b>","sz":12.0,"box":[62.4,150.9,275.8,174.9],"p":270,"i":2,"sec":"nachforschungen-ueber-corbin-payne"},{"t":"p","x":"• <b>Allwissend</b>: Wenn Fadi Malek die Szene betritt, gib ihm <t>fast allwissend 4</t>, erneuerbar als weiche Aktion. Das behindert jeden Angriff, den er sieht. • <b>Gott der Magie</b>: Fadi Malek kann jeden Zauber oder magischen Effekt auflösen, umkehren oder umlenken. Er kann dies als Einmischung tun, wenn er das Ziel ist, oder als eine weiche Aktion, wenn er es nicht ist (und so laufende Zauber beeinflusst). • <b>Riesenpavian</b>: Wenn Fadi Maleks <i>Verletzen oder unschädlich machen</i> den Maximalwert erreicht oder als harte Aktion kannst du das Spektrum zurücksetzen und sein Maximum auf 6 erhöhen. Dies schaltet Fadi Maleks Pavian-Aktionen frei (s. u.)","sz":9.0,"box":[62.4,179.4,276.3,344.4],"p":270,"i":3,"sec":"nachforschungen-ueber-corbin-payne"},{"t":"p","x":"• Jemanden mit <t>verwirrt 3</t>, <t>sensorisches Siegel 3</t> oder <t>Vergesslichkeit 3</t> schlagen • Alles über einen Eindringling wissen (<b>Die Dinge richtig kompliziert machen</b>) und ihn dazu zu bringen, an sich zu zweifeln (<t>Selbstzweifel 3</t>) oder drohen, die Informationen an die Behörden oder Feinde weiterzugeben (<b>Sie vor eine Wahl stellen</b>) • einen maßgeschneiderten Zauber wirken, um eine bestimmte Gruppe von Riss-Kräften zu deaktivieren (verbrennt 3 Stärken oder verleiht dem Ziel einen behindernden Stufe-3-Zustand) • Als Pavian: die Zähne blecken (<t>ängstlich 2</t> für alle, die es sehen) • Als Pavian: einen Gegner mit Wucht schlagen (<t>atemlos 3</t>) oder festhalten (<t>niedergehalten 3</t>) • Als Pavian: einen Gegner beißen (<t>Bisswunde 3</t>, kumulativ mit <t>atemlos</t>- oder <t>niedergehalten</t>)","sz":9.0,"box":[62.4,353.4,273.6,554.4],"p":270,"i":4,"sec":"nachforschungen-ueber-corbin-payne"},{"t":"p","x":"• Eindringlinge warnen, dass sie nicht wissen, worauf sie sich einlassen • die Augen schließen und mit den Fingern seine Stirn berühren, um die Geschichte einer Person lesen • Mit den Fingern mit einer Spur aus Goldstaub Hieroglyphen in die Luft zeichnen","sz":9.0,"box":[62.4,563.4,276.7,644.4],"p":270,"i":5,"sec":"nachforschungen-ueber-corbin-payne"},{"t":"threat","stars":"★★★★","name":"AMMIT, TOTENFRESSERIN","spectra":"","items":[],"box":[449.5,57.5,490.3,69.5],"p":270,"i":6,"sec":"nachforschungen-ueber-corbin-payne"},{"t":"p","x":"Fadi Maleks Leguan, früher als „Spike“ bekannt, ist jetzt ein Vertrauter, der die seelenfressende ägyptische Schimäre Ammit (Krokodil-Löwe-Nilpferd) channelt. Sie jagt und verschlingt Seelen, die sie als unwürdig für das nächste Leben erachtet und die in ihrer Gegenwart erstarren oder zögern.","sz":9.0,"box":[317.5,80.6,523.1,149.6],"p":270,"i":7,"sec":"nachforschungen-ueber-corbin-payne"},{"t":"sh","x":"<b>VERNICHTEN 6 / VERBANNEN 4 / KOMMUNIZIEREN –</b>","sz":12.0,"box":[317.5,160.1,530.6,172.1],"p":270,"i":8,"sec":"nachforschungen-ueber-corbin-payne"},{"t":"p","x":"• <b>Verurteilt</b>: Wer <t>markiert von Ammit</t> ist, wendet dies auf alles an, was dazu dient, Ammit auszuweichen oder sich zu verstecken, auch wenn anderen SC die Aktion machen(und bei <b>Sich der Gefahr stellen)</b>. • <b>Jenseits von Leben und Tod</b>: Stärken und Aktionen, die todesbezogene Kräfte darstellen, wirken nicht auf Ammit. • <b>Übernatürliche Macht</b>: Wenn Ammit einen Zustand aus dem Spektrum Verletzen oder unschädlich machen oder einen magischen Effekt erleidet, reduziert sich die Stufe um 2. • <b>Andersweltliche Pirscherin</b>: Wenn Ammit den Schauplatz betritt, gib ihr <t>mystische Sinne 2</t>. • <b>Seelenfresserin</b>: Wenn sie tötet, verschlingt sie die Seele. Zusätzlich zum Tod erhält die Seele den Zustand <t>für immer verloren 6</t>, und alle Zustände von Ammits <i>Vernichten</i> und <i>Verbannen</i> werden entfernt.","sz":9.0,"box":[317.5,176.6,532.1,377.6],"p":270,"i":9,"sec":"nachforschungen-ueber-corbin-payne"},{"t":"p","x":"• Trotz Verbannung auftauchen (<b>Die Dinge richtig kompliziert machen</b>, <i>Verbannen</i> zurücksetzen) • Eine Wand oder Barriere in ihrem Weg umstoßen oder durchschlagen (<b>Die Dinge richtig kompliziert machen</b> oder bis zu 3 Stärken verbrennen) • alle, die nah genug sind, mit Klauen und Bissen angreifen (<t>zerfleischt 4</t> für alle in der Nähe) • sich aus den Schatten auf ein ahnungsloses Opfer stürzen und es in Stücke reißen (<t>verstümmelt 5</t>) • einen Strahl flüssigen Feuers speien (<t>Verbrennungen 3</t>, wirkt auf einen kleinen Bereich)","sz":9.0,"box":[317.5,386.6,530.4,515.6],"p":270,"i":10,"sec":"nachforschungen-ueber-corbin-payne"},{"t":"p","x":"• Die Krokodilschnauze aus dem Schatten strecken. • Bereit sein, sich auf ihre Beute zu stürzen","sz":9.0,"box":[317.5,524.6,524.9,545.6],"p":270,"i":11,"sec":"nachforschungen-ueber-corbin-payne"}],"size":[595.276,841.89]},"271":{"tab":"","blocks":[{"t":"h","x":"NACHFORSCHUNGEN ÜBER DEN GEHEIMEN SCHMERZ","sz":16.0,"box":[78.8,68.9,257.8,101.9],"p":271,"i":0,"skip":true,"sec":"nachforschungen-ueber-den-geheimen-schmerz"},{"t":"p","x":"Nachdem die SC erfahren haben, dass Payne die erste Gralsritter:in in eine Schurk:in verwandelt hat, könnten die folgenden Hinweise dazu beitragen, sie auf den Weg zur Heilung ihres geheimen Schmerzes zu bringen (s. S. 262). Ein SC kann diese Verbindung <b>mystisch</b> herstellen, wenn er sich für Corbin Paynes magische Kräfte interessiert, oder <b>psychologisch</b>, wenn er sich dafür interessiert, wie Schurk:innen ticken. Beide Wege führen schließlich dazu, sich selbst zu betrachten.","sz":9.5,"box":[53.9,105.8,286.0,227.8],"p":271,"i":1,"sec":"nachforschungen-ueber-den-geheimen-schmerz"},{"t":"p","x":"Die Informationen lassen sich am besten in Form von <b>Gedanken, Eindrücken oder Eingebungen</b> vermitteln, die der SC erlebt. <b>Cineastisch gesehen solltest du diese Hinweise allmählich und mit Bedacht enthüllen</b>, da sie profunder und persönlicher Natur sind.","sz":9.5,"box":[53.9,236.5,285.8,296.1],"p":271,"i":2,"sec":"nachforschungen-ueber-den-geheimen-schmerz"},{"t":"p","x":"Eine Unterhaltung mit einem geeigneten NSC kann den SC zum Nachdenken anregen, z. B. mit:","sz":9.5,"box":[53.9,304.6,270.1,326.6],"p":271,"i":3,"sec":"nachforschungen-ueber-den-geheimen-schmerz"},{"t":"p","x":"• Einer Nebenfigur, die weise ist, sich auskennt oder den SC aufrichtig liebt","sz":9.5,"box":[53.9,338.1,274.0,360.1],"p":271,"i":4,"sec":"nachforschungen-ueber-den-geheimen-schmerz"},{"t":"p","x":"• Einer vertrauenswürdigen Therapeut:in, Psycholog:in, Coach, Geistlichen, Radiomoderator:in, Philosoph:in, Dichter:in usw. (wie Geraldine Granger aus <i>Scherben</i>, S. 295 oder Pfarrerin Williams aus <i>Daheim ist Daheim</i>, S. 217)","sz":9.5,"box":[53.9,368.8,286.1,428.3],"p":271,"i":5,"sec":"nachforschungen-ueber-den-geheimen-schmerz"},{"t":"p","x":"• Einer zuverlässigen mystischen Führer:in, Schaman:in, Hellsehende, jemand mit psychoaktiven Drogen, dem Geist eines Verstorbenen usw. (z. B. Ariadne in <i>Der Kult des Gottkönigs</i>, S. 126 oder Destiny Melancon in <i>Die Straßen bluten Neon</i>, S. 247)","sz":9.5,"box":[53.9,437.0,286.3,496.5],"p":271,"i":6,"sec":"nachforschungen-ueber-den-geheimen-schmerz"},{"t":"p","x":"Alternativ kannst du stimmungsvolle Szenen einbauen, die den geheimen Schmerz der Protagonist:innen beleuchten. Beschreibe, wie eine:r von ihnen allein durch die verregnete Stadt geht, in einer Bar trinkt, den Verkehr beobachtet oder eine andere nachdenkliche Szene. Bitte die Spieler:in zu beschreiben, woran der SC denkt und wie er sich fühlt, nicht nur in Bezug auf den aktuellen Fall, sondern im Großen und Ganzen. Ist der Charakter glücklich? Was belastet ihn? Was hat ihn letzte Nacht wachgehalten?","sz":9.5,"box":[53.9,502.3,285.4,624.3],"p":271,"i":7,"sec":"nachforschungen-ueber-den-geheimen-schmerz"},{"t":"sh","x":"<b>DEN WEG ZUR HEILUNG FREIMACHEN</b>","sz":10.0,"box":[54.3,637.9,261.4,647.9],"p":271,"i":8,"sec":"nachforschungen-ueber-den-geheimen-schmerz"},{"t":"p","x":"Wie unter Heilung des geheimen Schmerzes (s. S. 262) beschrieben, können die Hinweise einen SC dazu bringen, <b>Nachforschungen</b> anzustellen, ob er selbst einen geheimen Schmerz hat. Wenn ein Charakter von seinem Schmerz erfährt, offenbart sich sein Zustand <t>verwundet</t>. Wenn er weiter recherchiert und eine Anleitung zur Heilung erhält (der unterste Hinweis in jedem Set), biete der Spieler:in die Möglichkeit, dafür Aufmerksamkeit zu verwenden.","sz":9.5,"box":[53.9,653.5,283.0,763.0],"p":271,"i":9,"sec":"nachforschungen-ueber-den-geheimen-schmerz"},{"t":"sh","x":"<b>PSYCHOLOGISCHE HINWEISE</b>","sz":10.0,"box":[309.4,62.8,469.6,72.8],"p":271,"i":10,"sec":"nachforschungen-ueber-den-geheimen-schmerz"},{"t":"card","x":"<b>Jeder in der Stadt trägt einen geheimen Schmerz in sich</b>, keinen vorübergehenden oder oberflächlichen, sondern etwas tief Verwurzeltes, Wesentliches und Existenzielles: seine conditio humana, den Schmerz, ein Mensch in der Stadt zu sein.","sz":null,"k":"yellow","box":[309.3,78.3,541.7,162.1],"p":271,"i":11,"sec":"nachforschungen-ueber-den-geheimen-schmerz"},{"t":"card","x":"<b>Selbst die gutmütigste Seele kann, wenn sie großen Schmerz erfährt, anderen schaden wollen.</b> Jeder, der einen geheimen Schmerz in sich trägt, kann zur Schurk:in werden.","sz":null,"k":"yellow","box":[309.3,171.4,541.7,230.1],"p":271,"i":12,"sec":"nachforschungen-ueber-den-geheimen-schmerz"},{"t":"card","x":"<b>Auch du (der SC) trägst einen Schmerz mit dir herum.</b> Du dachtest, du könntest ihn ignorieren, aber er scheint eine tickende Zeitbombe zu sein. <b>Wenn er ausbricht, könnte er dich zur schlimmsten Schurk:in machen, die die Stadt je gesehen hat.</b>","sz":null,"k":"yellow","box":[309.3,239.3,541.7,323.1],"p":271,"i":13,"sec":"nachforschungen-ueber-den-geheimen-schmerz"},{"t":"card","x":"<b>Letztlich kannst nur du den Schmerz heilen, indem du Aufmerksamkeit nach innen richtest und dich ihm stellst.</b> Es ist ein langer Weg, mit Verzicht auf Dinge, die dir wichtig sind, aber die Belohnung ist es wert, nicht nur für dich, sondern für Alle um dich herum, die du verletzt hast und noch verletzen wirst.","sz":null,"k":"yellow","box":[309.3,332.4,541.7,428.5],"p":271,"i":14,"sec":"nachforschungen-ueber-den-geheimen-schmerz"},{"t":"sh","x":"<b>MYSTISCHE HINWEISE</b>","sz":10.0,"box":[309.4,443.6,433.7,453.6],"p":271,"i":15,"sec":"nachforschungen-ueber-den-geheimen-schmerz"},{"t":"card","x":"Paynes Einfluss auf die Gralsritter:in zieht seine Macht aus dem geheimen Schmerz der Ritter:in, der die ganze Zeit in ihr schwärt.","sz":null,"k":"yellow","box":[309.3,458.2,541.7,504.3],"p":271,"i":16,"sec":"nachforschungen-ueber-den-geheimen-schmerz"},{"t":"card","x":"Wenn er wirklich den Schmerz der Menschen aktivieren kann, hat Payne jeden in der Stadt in seiner Gewalt, denn Schmerz ist universell.","sz":null,"k":"yellow","box":[309.3,513.5,541.7,559.9],"p":271,"i":17,"sec":"nachforschungen-ueber-den-geheimen-schmerz"},{"t":"card","x":"<b>Der geheime Schmerz ist zu persönlich, als dass er von außen entfernt werden könnte.</b> Keine mundane oder magische Behandlung kann ihn heilen, ohne das Wesen des Betroffenen in etwas Abscheuliches zu verwandeln.","sz":null,"k":"yellow","box":[309.3,569.1,541.7,640.5],"p":271,"i":18,"sec":"nachforschungen-ueber-den-geheimen-schmerz"},{"t":"card","x":"<b>Der Weg zur Heilung ist weder wissenschaftlich noch magisch</b>: Der Mensch hat die Kraft, seine Aufmerksamkeit auf den eigenen Schmerz zu richten, ihn zu verstehen und zu heilen. Diesen Weg deuten viele Mythen und Sagen an, aber immer als lange und fast unüberwindbare Herausforderung.","sz":null,"k":"yellow","box":[309.3,649.4,541.7,745.9],"p":271,"i":19,"sec":"nachforschungen-ueber-den-geheimen-schmerz"}],"size":[595.276,841.89]},"272":{"tab":"","blocks":[{"t":"h","x":"DER HEILENDE MONOLOG","sz":16.0,"box":[53.9,62.2,219.4,78.2],"p":272,"i":0,"skip":true,"sec":"der-heilende-monolog"},{"t":"p","x":"Du kannst das Folgende als die Worte einer Führer:in oder Mentor:in verwenden, die dem Charakter beibringen, wie er Aufmerksamkeit nutzt, um zu heilen.","sz":9.5,"box":[53.9,82.2,285.1,116.7],"p":272,"i":1,"sec":"der-heilende-monolog"},{"t":"ro","x":"„Wie heilt man Schmerz?","sz":9.0,"box":[53.9,123.8,178.1,132.8],"p":272,"i":2,"sec":"der-heilende-monolog"},{"t":"ro","x":"Sei bei ihm. Lauf nicht davor weg, suhle dich nicht darin, unterdrücke nicht. Sei bei ihm.","sz":9.0,"box":[53.9,140.3,269.9,170.9],"p":272,"i":3,"sec":"der-heilende-monolog"},{"t":"ro","x":"Begreife, dass jeder Mensch verwundet ist. Fang an, die Wunden anderer Menschen hinter ihren Worten und Taten zu sehen. Auch sie wurden verletzt.","sz":9.0,"box":[53.9,178.3,286.1,219.7],"p":272,"i":4,"sec":"der-heilende-monolog"},{"t":"ro","x":"Begreife, dass diejenigen, die dich verletzt haben, auch verletzt sind. Das macht das, was sie getan haben, nicht richtig, aber so ist es nun einmal.","sz":9.0,"box":[53.9,227.2,280.7,268.6],"p":272,"i":5,"sec":"der-heilende-monolog"},{"t":"ro","x":"Was tust du mit diesem Schmerz? Lässt du dich von ihm treiben? Lässt du dich aufzehren? Gibst du ihn an einen anderen weiter? Er will weitergehen, und wenn du ihn weitergibst, verlässt er dich für eine Weile. Es ist eine Erleichterung, aber eine temporäre.","sz":9.0,"box":[53.9,276.1,286.1,349.9],"p":272,"i":6,"sec":"der-heilende-monolog"},{"t":"ro","x":"Du musst dir im Klaren sein, dass alle Versuche, den Schmerz zu unterdrücken, mit noch mehr Schmerz enden.","sz":9.0,"box":[53.9,357.3,286.1,387.9],"p":272,"i":7,"sec":"der-heilende-monolog"},{"t":"ro","x":"Was soll man mit diesem Schmerz tun, wenn man ihn heilen will? Schau ihn dir an. Schenk ihm Aufmerksamkeit. Versuch nicht, ihn zu ändern.","sz":9.0,"box":[53.9,395.4,275.3,436.8],"p":272,"i":8,"sec":"der-heilende-monolog"},{"t":"ro","x":"Spüre ihn, aber ertrink nicht in ihm. Halte seine Hand, nur ganz kurz. Gib ihm Raum, aber lass ihn nicht überhand nehmen. Du bist bei dem Schmerz, und du spürst seine Wurzel, den Grund, warum er da ist. Du akzeptierst ihn als etwas, das da ist, als Tatsache, die du ertragen musst. Wenn du das tust, schmerzt es nicht mehr so sehr.","sz":9.0,"box":[53.9,444.3,286.1,528.9],"p":272,"i":9,"sec":"der-heilende-monolog"},{"t":"ro","x":"Du akzeptierst ihn.","sz":9.0,"box":[53.9,536.4,156.5,545.4],"p":272,"i":10,"sec":"der-heilende-monolog"},{"t":"ro","x":"Du akzeptierst, dass du Schwächen hast – du bist, was du bist, du hast dich nicht selbst geschaffen, und es liegt nicht in deiner Macht, alles zu ändern.","sz":9.0,"box":[53.9,552.8,269.9,594.2],"p":272,"i":11,"sec":"der-heilende-monolog"},{"t":"ro","x":"Du akzeptierst, dass du sterben wirst – das liegt in der Natur dieser Existenz und macht dich zu dem, was du bist.","sz":9.0,"box":[53.9,601.7,280.7,632.3],"p":272,"i":12,"sec":"der-heilende-monolog"},{"t":"ro","x":"Du akzeptierst, dass du schwach bist, dass andere dich verletzen können – du bist auch nur ein Mensch.","sz":9.0,"box":[53.9,639.8,286.1,670.4],"p":272,"i":13,"sec":"der-heilende-monolog"},{"t":"ro","x":"Atme tief durch. Du akzeptierst deine Lebensumstände, deine Lage, und damit hört der Schmerz auf.","sz":9.0,"box":[53.9,677.8,275.3,708.4],"p":272,"i":14,"sec":"der-heilende-monolog"},{"t":"ro","x":"Morgen tust du das wieder. Du hast einen weiten Weg vor dir.“","sz":9.0,"box":[53.9,715.9,269.9,735.7],"p":272,"i":15,"sec":"der-heilende-monolog"},{"t":"h","x":"AKT 2","sz":23.0,"box":[309.0,63.4,365.5,86.4],"p":272,"i":16,"skip":true,"sec":"akt-2"},{"t":"p","x":"Akt 2 beginnt, wenn das Team erfährt, wie es Corbin Tower erreichen kann, was zu einer direkten Konfrontation führt: Die SC wagen sich dorthin und stellen sich dem Avatar des Fischerkönigs, oder sie müssen reagieren, wenn Payne die Beherrschung verliert und aus seiner Zuflucht auftaucht, um die Innenstadt in einem Strudel aus Schmerz zu ertränken. Leider ist das Team noch nicht darauf vorbereitet, sich dem Baulöwen zu stellen. Stattdessen erhält es eine Lektion in Demut und sieht, was passiert, wenn der geheime Schmerz die Oberhand gewinnt.","sz":13.0,"box":[309.0,94.3,539.6,310.3],"p":272,"i":17,"sec":"akt-2"},{"t":"h","x":"DIE ZWEITE GRALSRITTER:IN","sz":16.0,"box":[334.8,328.9,523.7,344.9],"p":272,"i":18,"skip":true,"sec":"die-zweite-gralsritter-in"},{"t":"p","x":"Wenn das Team der zweiten Gralsritter:in gegenübersteht, hat es vielleicht schon ein gutes Bild von der Vergangenheit und davon, was Payne der Stadt antut. <b>Die zweite Gralsritter:in weiß, wie man <u>Corbin Tower</u> findet</b>, aber nicht, wie man ihn heilen kann (dafür muss das Team die letzte Gralsritter:in finden).","sz":9.5,"box":[309.0,348.8,539.0,420.8],"p":272,"i":19,"sec":"die-zweite-gralsritter-in"},{"t":"sh","x":"<b>ÜBER CORBIN PAYNE</b>","sz":10.0,"box":[309.4,434.4,423.6,444.4],"p":272,"i":20,"sec":"die-zweite-gralsritter-in"},{"t":"card","x":"<b>Die zweite Gralsritter:in hat Corbin Payne ebenfalls korrumpiert.</b> Nachforschungen über ihre Vergangenheit enthüllen Einzelheiten über ihre Beziehung zu Payne. Die Untersuchung der mystischen Zustände ergibt die gleichen Hinweise über die Nimmer heilende Wunde (s. S. <u>Die erste Gralsritter:in,</u> S. 265).","sz":null,"k":"yellow","box":[309.3,451.3,541.7,547.8],"p":272,"i":21,"sec":"die-zweite-gralsritter-in"},{"t":"card","x":"Dies bestätigt, dass Payne wohlmeinende Menschen methodisch und systematisch in Erzbösewicht:innen verwandelt und damit für das von ihnen verursachte Leid verantwortlich ist.","sz":null,"k":"yellow","box":[309.3,556.7,541.7,615.7],"p":272,"i":22,"sec":"die-zweite-gralsritter-in"},{"t":"sh","x":"<b>ÜBER CORBIN TOWER</b>","sz":10.0,"box":[309.4,629.0,428.2,639.0],"p":272,"i":23,"sec":"die-zweite-gralsritter-in"},{"t":"card","x":"<b>Corbin Tower ist Paynes letztes Projekt, die Bauruine eines Hochhauses im Stadtzentrum.</b> Er ist die Enklave der Gralsburg, verborgen durch Magie und den Nebel.","sz":null,"k":"yellow","box":[309.3,646.3,541.7,705.3],"p":272,"i":24,"sec":"die-zweite-gralsritter-in"},{"t":"card","x":"<b>Wer reinen Herzens ist, kann Corbin Tower finden.</b> Allerdings hat man <b>nur eine Chance</b>: War man dort, kann man nie wieder zurückkehren, egal wie rein das Herz ist.","sz":null,"k":"yellow","box":[309.3,714.5,541.7,773.3],"p":272,"i":25,"sec":"die-zweite-gralsritter-in"}],"size":[595.276,841.89]},"273":{"tab":"","blocks":[{"t":"card","x":"Die Magie des Turms verbirgt ihn, ist aber auch das Schlupfloch, durch das man ihn finden kann. Wer sich im Rahmen einer <b>bewussten Queste</b> auf die Suche nach der Gralsburg begibt, kann sie finden, wenn sein Herz rein ist.","sz":null,"k":"yellow","box":[54.1,54.1,286.6,138.0],"p":273,"i":0,"sec":"die-zweite-gralsritter-in"},{"t":"card","x":"Genauer gesagt kann die zweite Gralsritter:in dem Team das Relikt <b>Galahads Dolch</b> überreichen, das als Wegweiser zum Corbin Tower dient (s. u., zusätzliches Thema).","sz":null,"k":"yellow","box":[54.1,147.2,286.6,205.9],"p":273,"i":1,"sec":"die-zweite-gralsritter-in"},{"t":"card","x":"<b>Auf der <i>Stadtkarte</i> dient Galahads Dolch als Rätsel.</b> Wenn man den Griff und die Klinge kombiniert, auf dem Stadtplan platziert und auf die Standorte der beiden bekannten Gralsritter ausrichtet, markiert das Loch im Knauf den Standort von Corbin Tower.","sz":null,"k":"yellow","box":[54.1,215.1,286.6,299.2],"p":273,"i":2,"sec":"die-zweite-gralsritter-in"},{"t":"sh","x":"<b>GALAHADS DOLCH</b>","sz":12.0,"box":[65.3,340.4,179.4,352.4],"p":273,"i":3,"sec":"die-zweite-gralsritter-in"},{"t":"p","x":"<i>Relikt</i>","sz":10.0,"box":[65.3,362.2,91.2,372.2],"p":273,"i":4,"sec":"die-zweite-gralsritter-in"},{"t":"h","x":"IDENTITÄT","sz":10.0,"box":[65.3,383.6,111.5,393.6],"p":273,"i":5,"sec":"die-zweite-gralsritter-in"},{"t":"p","x":"Wo ist die Gralsburg?","sz":9.0,"box":[65.3,398.4,149.7,407.4],"p":273,"i":6,"sec":"die-zweite-gralsritter-in"},{"t":"h","x":"STÄRKEN","sz":10.0,"box":[65.3,419.1,105.9,429.1],"p":273,"i":7,"sec":"die-zweite-gralsritter-in"},{"t":"card","x":"<b><i>Griff weist zur Burg</i></b>, <i>Moralischer Kompass</i>, <i>Gute Absichten</i>, <i>Juwelenbesetzter Dolch</i>, <i>Schärfste Klinge</i>, <i>Zerstört Illusionen</i>, <i>Stärker bei einer Ritter:in</i>, <i>Artus-Legenden aufspüren</i>, <i>Nahegelegene Enklaven aufspüren</i>, <i>Nimmer heilende Wunde zufügen</i>","sz":null,"k":"yellow","box":[65.4,432.6,271.0,490.8],"p":273,"i":8,"sec":"die-zweite-gralsritter-in"},{"t":"h","x":"SCHWÄCHEN","sz":10.0,"box":[65.3,502.6,122.2,512.6],"p":273,"i":9,"sec":"die-zweite-gralsritter-in"},{"t":"card","x":"<i>Nicht für Unwürdige</i>, <i>Untersteht einer höheren Macht</i>, <i>Grüne Ritter:in</i>, <i>Besessen vom Gral</i>","sz":null,"k":"yellow","box":[65.4,516.1,271.3,538.3],"p":273,"i":10,"sec":"die-zweite-gralsritter-in"},{"t":"h","x":"THEMENVERBESSERUNG","sz":10.0,"box":[65.3,550.1,172.0,560.1],"p":273,"i":11,"sec":"die-zweite-gralsritter-in"},{"t":"p","x":"<b>Perfektionierte Wunde:</b> Wenn du mit diesen Stärken <b>Mit aller Gewalt</b> zuschlägst und dich entscheidest, <t>Nimmer heilende Wunde</t> zuzufügen, erhöhst du deine Stufe um 3 statt um 1. Die Nimmer heilende Wunde kann das Ziel nicht töten, sondern nur verkrüppeln und in eine Schurk:in verwandeln.","sz":9.0,"box":[65.3,564.9,273.3,633.9],"p":273,"i":12,"sec":"die-zweite-gralsritter-in"},{"t":"card","x":"CORBIN TOWER","sz":null,"k":"yellow","box":[324.9,61.9,459.9,86.4],"p":273,"i":13,"sec":"die-zweite-gralsritter-in"},{"t":"p","x":"Corbin Tower, die Enklave der Gralsburg, ist das unvollendete Hochhaus Corbin Paynes: Ein 50-stöckiges Gerippe mit teilweise vollendeten Stockwerken und ohne Fassade. Der größte Teil scheint eine verlassene Baustelle zu sein, doch einige Durchgänge führen in glitzernde Art-déco-Hallen aus der Jahrhundertwende, wo die Gralsburg-Enklave durchscheint und mit Paynes persönlicher Geschichte verschmilzt. Die Durchgänge sind unterschiedlich: von einer neonumrahmten Art-déco-Tür, die eindeutig fehl am Platz ist, bis zu einer wabernden Nebelbank, hinter der das Team sich in einer anderen Zeit wiederfindet.","sz":9.5,"box":[309.0,88.8,541.1,235.8],"p":273,"i":14,"sec":"die-zweite-gralsritter-in"},{"t":"sh","x":"<b>CORBIN TOWER FINDEN</b>","sz":10.0,"box":[309.4,249.4,441.2,259.4],"p":273,"i":15,"sec":"die-zweite-gralsritter-in"},{"t":"p","x":"Wie die zweite Gralsritter:in erklärt, kann man Corbin Tower weder mit gewöhnlichen noch mit magischen Mitteln finden. Dazu muss ein SC entweder:","sz":9.5,"box":[309.0,265.0,536.4,299.5],"p":273,"i":16,"sec":"die-zweite-gralsritter-in"},{"t":"p","x":"• Galahads Dolch und den Stadtplan kombinieren.","sz":9.5,"box":[309.0,311.0,522.0,320.5],"p":273,"i":17,"sec":"die-zweite-gralsritter-in"},{"t":"p","x":"• Sich auf die Queste der Suche nach der Gralsburg begeben. Dann stellt er <b>Nachforschungen</b> mit Stärken an, die Güte, Mitgefühl und Reinheit des Herzens beschreiben, mit relevanten Merkmalen von Galahads Dolch und/oder dem Zustand <t>geheilt</t>, falls er ihn hat. Der Turm ist <t>im Nebel versteckt 5</t>.","sz":9.5,"box":[309.0,329.1,540.9,401.1],"p":273,"i":18,"sec":"die-zweite-gralsritter-in"},{"t":"sh","x":"<b>DER UNVOLLENDETE WOLKENKRATZER</b>","sz":10.0,"box":[309.4,417.6,527.7,427.6],"p":273,"i":19,"sec":"die-zweite-gralsritter-in"},{"t":"ro","x":"Die Straße, die zum Wolkenkratzer führt, erstreckt sich durch eine dichte Nebelbank, die euch den Blick auf das, was euch erwartet, verstellt. Ihr stürzt euch hinein und geht weiter, vertraut allein auf euren Glauben. Als es scheint, ihr hättet euch wirklich verirrt, seht ihr über euch rote Lichter, die den Nebel wie Blutstropfen färben. Ihr kommt an einen rostigen Maschendrahtzaun. Das Tor ist mit einer Kette verschlossen, aber die Scharniere zerfallen. Auf einer alten Tafel steht: Payne Constructions – Vorsicht Baustelle. Das umgestürzte, von Schimmel zerfressene Plakat zeigt das Gesicht des Bauunternehmers mit der einst blitzblanken Aufschrift CORBIN TOWER. Über euch, unter dunklem Himmel, erhebt sich ein heruntergekommener, unvollendeter Wolkenkratzer. Er scheint verlassen, leer, und doch spürt ihr in euren Knochen, dass ihr euch umdrehen und weglaufen solltet.","sz":9.0,"box":[317.5,431.6,538.9,667.4],"p":273,"i":20,"sec":"die-zweite-gralsritter-in"},{"t":"p","x":"Die profanen Teile des Turms, der ursprünglich als Luxushotel, Casino und Bürogebäude gedacht war, stehen leer und sind den Elementen ausgesetzt. Sie dienen dazu, Stimmung und Spannung aufzubauen, können aber auch Risiken für die SC darstellen:","sz":9.5,"box":[309.0,676.4,541.3,735.9],"p":273,"i":21,"sec":"die-zweite-gralsritter-in"}],"size":[595.276,841.89]},"274":{"tab":"","blocks":[{"t":"p","x":"• <b>Umwelteinflüsse</b>: Witterung (Wind, Regen, Wasseransammlung, Blitzschlag), eingestürzte Böden und Treppen, marode Leitern, nicht funktionierende Fahrstühle, rutschige Simse, spitze Stahlstangen, verrostete Maschinen (z. B. Kräne)","sz":9.5,"box":[309.0,62.5,538.5,122.0],"p":274,"i":0,"sec":"die-zweite-gralsritter-in"},{"t":"p","x":"• <b>Legendäre Einwohner</b>: Gralsunholde oder avalonische Diener:innen","sz":9.5,"box":[309.0,130.7,537.7,152.7],"p":274,"i":1,"sec":"die-zweite-gralsritter-in"},{"t":"p","x":"• <b>Schmerz-Fallout</b>: Unsichtbare Wirbel voller Trauma und Elend plagen bestimmte Bereiche im Gebäude.","sz":9.5,"box":[309.0,161.3,540.6,183.3],"p":274,"i":2,"sec":"die-zweite-gralsritter-in"},{"t":"p","x":"• <b>Corbin Paynes Gegenwart</b>: Der Versuch, Payne psychisch zu lokalisieren, schafft eine emotionale Verbindung zu ihm, die es ihm ermöglicht, den betreffenden SC zu verletzen (s. S. <u>Corbin Payne höchstpersönlich,</u> S. 262)","sz":9.5,"box":[309.0,192.0,524.0,251.5],"p":274,"i":3,"sec":"die-zweite-gralsritter-in"},{"t":"card","x":"<b>Der Blick jenseits des Nebels</b> offenbart eine trostlose und verlassene mittelalterliche Burg. Gleichzeitig sind unermesslicher Schmerz (der Fischerkönig) und großes Mitgefühl (der Gral) zu spüren.","sz":null,"k":"yellow","box":[309.3,263.8,541.7,335.2],"p":274,"i":4,"sec":"die-zweite-gralsritter-in"},{"t":"threat","stars":"★★★","name":"GRALSUNHOLD","spectra":"","items":[],"box":[394.3,369.3,424.9,381.3],"p":274,"i":5,"sec":"die-zweite-gralsritter-in"},{"t":"p","x":"Ein Gralsunhold ist ein Wesen, das sich auf der Suche nach Corbin Payne oder dem Gral im Wolkenkratzer verirrt und den Schmerz-Fallout des Gebäudes absorbiert hat. Unholde erscheinen wie Stadtstreicher:innen oder Hausbesetzer:innen, doch wenn sie kämpfen, blitzt ihre geisterhafte, ritterliche Erscheinung auf. Sie wollen ihren Schmerz auf andere übertragen. Die Heilung eines Gralsunholds erfordert eine unumkehrbare Jetzt reicht’s!-Aktion.","sz":9.0,"box":[317.5,392.5,530.5,497.5],"p":274,"i":6,"sec":"die-zweite-gralsritter-in"},{"t":"sh","x":"<b>VERLETZEN ODER UNSCHÄDLICH MACHEN 4 / HEI- LEN – / AUSHUNGERN ODER ERSTICKEN –</b>","sz":12.0,"box":[317.5,508.0,522.8,532.0],"p":274,"i":7,"sec":"die-zweite-gralsritter-in"},{"t":"p","x":"• <b>Nicht ganz da</b>: Wenn der Gralsunhold die Szene betritt, gib ihm <t>benommen 1</t>. • <b>Schmerzüberfluss</b>: Wenn man dem Unhold Schaden zufügt, nimmt man selbst den selben Zustand, mit einer um 2 niedrigeren Stufe. Der Schmerz kommt von innen, also darf man <b>Sich der Gefahr stellen</b> nur mit Stärken, die Schmerz widerstehen.","sz":9.0,"box":[317.5,536.5,528.2,617.6],"p":274,"i":8,"sec":"die-zweite-gralsritter-in"},{"t":"p","x":"• Jemanden mit einem imaginären Schwert fühlbar aufschlitzen (<t>stechender Schmerz 3</t>) • Jemanden suchen, um ihm Schmerz zuzufügen (entfernt <t>benommen 1</t> und verleiht <i>Emotionale Wesen spüren</i>)","sz":9.0,"box":[317.5,626.5,522.7,683.5],"p":274,"i":9,"sec":"die-zweite-gralsritter-in"},{"t":"p","x":"• In die Etage wandern, in der sich das Team befindet, ohne es zu bemerken • Ein unsichtbares Schwert heben, das kurz glüht","sz":9.0,"box":[317.5,692.5,522.1,725.5],"p":274,"i":10,"sec":"die-zweite-gralsritter-in"}],"size":[595.276,841.89]},"275":{"tab":"","blocks":[{"t":"threat","stars":"★★★","name":"AVALONISCHE DIENER:IN","spectra":"","items":[],"box":[187.0,46.8,217.6,58.8],"p":275,"i":0,"sec":"die-zweite-gralsritter-in"},{"t":"p","x":"Avalonische Diener:innen sind Beschwörungen der Gralsburg-Enklave. Sie sind elfenhaft aussehende Jungfern und Jünglinge in feinen Gewändern, die zwischen Mittelalter und Jahrhundertwende schwanken. Man hat sie in Avalon in den Künsten der Heilung und Magie ausgebildet und in den Dienst des Fischerkönigs gestellt, um seine Schmerzen zu lindern. Zum Leidwesen aller Eindringlinge macht der Charme der Diener:innen süchtig, und Eindringlinge liegen oft in ihren Armen, bis Corbin Payne sie findet.","sz":9.0,"box":[62.4,69.9,277.2,186.9],"p":275,"i":1,"sec":"die-zweite-gralsritter-in"},{"t":"sh","x":"<b>VERLETZEN ODER UNSCHÄDLICH MACHEN 1 / ZUR KAPITULATION BEWEGEN 4</b>","sz":12.0,"box":[62.4,197.5,264.5,221.5],"p":275,"i":2,"sec":"die-zweite-gralsritter-in"},{"t":"p","x":"• <b>Freundlichkeit ausstrahlen</b>: Wenn man eine avalonische Diener:in verletzt, nimmt man <t>bedauern 3</t>. • <b>Süchtig nach Heilung</b>: Als weiche Aktion gegen ein williges Ziel oder als harte gegen jedes andere können sie bis zu drei Zustandsstufen Schmerz, negative Emotionen oder Verletzungen entfernen. Pro entfernte Stufe erhält das Ziel 1 Stufe <t>angenehme Erleichterung</t>, einen Zustand, der es dazu zwingt, bei der avalonischen Diener:in zu bleiben (zum Weggehen muss man <b>Ein Risiko Eingehen</b>).","sz":9.0,"box":[62.4,225.9,276.3,355.1],"p":275,"i":3,"sec":"die-zweite-gralsritter-in"},{"t":"p","x":"• Salbe auf jemanden auftragen, den sie geheilt haben (<t>angenehme Erleichterung 2</t>) • Pulver auf eine aggressive Person pusten (<t>schläfrig 3</t>)","sz":9.0,"box":[62.4,363.9,268.5,408.9],"p":275,"i":4,"sec":"die-zweite-gralsritter-in"},{"t":"p","x":"• Sich anbieten, jemandem die Hände aufzulegen und Leiden zu lindern • Das Team warnen, dass der Fischerkönig nicht mehr zu heilen ist","sz":9.0,"box":[62.4,417.9,260.7,462.9],"p":275,"i":5,"sec":"die-zweite-gralsritter-in"},{"t":"sh","x":"<b>DIE LEBENDEN ERINNERUNGEN</b>","sz":10.0,"box":[54.3,483.0,227.7,493.0],"p":275,"i":6,"sec":"die-zweite-gralsritter-in"},{"t":"p","x":"In einigen Räumen und Gängen des Wolkenkratzers stellen Corbin Payne und seine Enklave Szenen aus seinem Leben nach. Die Figuren in den Szenen sind empfindungs- und substanzlose Beschwörungen, animierte Puppen, die eine Erinnerung wiedergeben.","sz":9.5,"box":[53.9,498.6,279.5,558.1],"p":275,"i":7,"sec":"die-zweite-gralsritter-in"},{"t":"p","x":"Diese Szenen können wichtige Informationen für die Ermittlungen des Teams gegen Payne liefern oder fehlende Steinchen ergänzen. Mache Auslassungen oder Anpassungen, um zu vermeiden, dass du bestimmte Details über die dritte Gralsritter:in enthüllst.","sz":9.5,"box":[53.9,566.7,283.3,626.2],"p":275,"i":8,"sec":"die-zweite-gralsritter-in"},{"t":"p","x":"Zeug:innen solcher Szene können von den Emotionen angesteckt werden. Du kannst die SC warnen und ihnen als <b>Angriff mit Ansage</b> einen Zustand verleihen, der ihre <b>Nachforschungen</b> beeinträchtigt.","sz":9.5,"box":[53.9,634.9,281.9,682.0],"p":275,"i":9,"sec":"die-zweite-gralsritter-in"},{"t":"p","x":"Die Hinweise sind in chronologischen Reihenfolge angeordnet, aber die SC können sie in beliebiger Reihenfolge finden. <b>Die Hinweise auf Rio und die <u>Abwrackwerft</u> sind von entscheidender Bedeutung.</b>","sz":9.5,"box":[53.9,690.6,285.8,737.7],"p":275,"i":10,"sec":"die-zweite-gralsritter-in"},{"t":"card","x":"<b>Schüsse auf dem roten Teppich</b>: Der Bereich vor dem Wolkenkratzer stellt die Schüsse nach, bei der der Schütze – Paynes nach seinem Ebenbild geschaffene Beschwörung – dem Baulöwen beim Aussteigen aus der Limousine die Nimmer heilende Wunde zufügte. Es ist fast unerträglich, hier zu sein, nicht nur wegen des unglaublichen Schmerzes, den er in diesem Moment erlitten hat, sondern wegen dem, was er im Nachhinein über diesen Moment empfindet: Wut, Bitterkeit und völlige Verzweiflung.","sz":null,"k":"yellow","box":[309.3,54.1,541.7,200.4],"p":275,"i":11,"sec":"die-zweite-gralsritter-in"},{"t":"card","x":"<b>Krystal Knigh</b>t: Ein Raum sieht wie das Büro einer Psychoanalytiker:in der Jahrhundertwende aus, Payne liegt auf dem Sofa und Dr. Knight sitzt im Sessel. Diese Erinnerung zeigt Knights Versuch, Payne zu heilen, und seine Fähigkeit, sie zu verletzen. Die vorherrschende Emotion ist Scham, wobei Payne eine Mischung aus Befriedigung und Schuldgefühlen aus seiner Demütigung der Psychiaterin zieht.","sz":null,"k":"yellow","box":[309.3,209.7,541.7,330.9],"p":275,"i":12,"sec":"die-zweite-gralsritter-in"},{"t":"card","x":"<b>Die vierte Ritterin (Rio Beaumont)</b>: Dies ist eine von Paynes Wohnungen, in die er sich nach den Schüssen auf dem roten Teppich zurückgezogen hat. Er ist ein beeindruckender Mann, aber durch seine schwärende Wunde verkrüppelt, stützt sich auf einen Stock und trägt einen schmutzigen Bademantel. Ein junges Mädchen (Rio Beaumont, <b>aber ihr Name fällt hier nicht</b>) sagt, es sei ihr Schicksal, den Gral zu finden und sowohl Payne als auch die Stadt zu heilen. Payne fragt verbittert: „Was weißt du schon?“ und zeigt den Gral in Form eines fleckigen Waschbeckens. Als sie hineinschaut, verwandelt sich die Szene in ein fleckiges Aquarell und verschwindet in grauem Nebel. <b>Sie fühlt sich verloren</b>, entfremdet und ahnungslos und verschließt sich. <b>Payne spürt Hoffnung</b>, denn er glaubt, dass sie eines Tages zurückkehren wird, um ihn zu heilen.","sz":null,"k":"yellow","box":[309.3,340.1,541.7,586.4],"p":275,"i":13,"sec":"die-zweite-gralsritter-in"},{"t":"card","x":"<b>Armand Kai</b>: Dies ist der Raum, in dem Payne Armand Kai seine Wunde offenbarte (in seiner Gestalt des Avatars der Agonie, s. <u>Corbin Payne höchstpersönlich,</u> S. 262). Die Szene enthüllt Armands wahres Motiv für die Suche nach dem Stein der Weisen – seine Angst vor dem Tod – und erfüllte ihn mit lähmendem Entsetzen und Ekel. Payne empfindet Freude, aber er ist auch traurig über den Verlust eines möglichen Heilmittels.","sz":null,"k":"yellow","box":[309.3,595.6,541.7,729.5],"p":275,"i":14,"sec":"die-zweite-gralsritter-in"}],"size":[595.276,841.89]},"276":{"tab":"","blocks":[{"t":"card","x":"<b>Vince Beaumont:</b> Dies ist der Raum, in dem Vince, der Jahrzehnte später in einem anderen Körper reinkarnierte, Corbin Payne gefunden und getötet hat, um sich für die Entführung seiner Tochter zu rächen. Der Gral lässt Payne auferstehen, was Beaumonts Gewalt und <b>Wut</b> ins Unermessliche steigert. Außerdem fühlt Beaumont unsagbaren <b>Kummer</b>. Payne, der sich nicht wehrt, ist perplex und kurzzeitig erleichtert, wenn er stirbt, und immer, wenn er wiederbelebt wird, übermannen ihn völlige Enttäuschung und Angst.","sz":null,"k":"yellow","box":[54.1,54.1,286.6,213.1],"p":276,"i":0,"sec":"die-zweite-gralsritter-in"},{"t":"card","x":"<b>Andere Gralsritter:innen</b>: Für jede Gralsritter:in, die Payne zum Ritter geschlagen hat, gibt es weitere Szenen, die über das Gebäude verstreut sind, einschließlich der Protagonist:innen, Nebenfiguren oder der einen oder anderen Nemesis, falls erforderlich.","sz":null,"k":"yellow","box":[54.1,222.0,286.6,305.9],"p":276,"i":1,"sec":"die-zweite-gralsritter-in"},{"t":"card","x":"<b>Der Abwassertunnel</b>: Unter dem Gebäude liegt ein Abwassertunnel, der bis zur Küste reicht und in die <u>Abwrackwerft</u> mündet. Obwohl er keine Erinnerung ist, strahlt der Tunnel Gefühle von Schwermut, stiller Nachdenklichkeit und zerbrechlichem <b>Frieden</b> aus. Dort liegt ein Boot, mit dem <b>Payne zum Fischen hinausfährt</b> (so weiß das Team, wo es ihn treffen kann, wenn es den Turm verlassen hat).","sz":null,"k":"yellow","box":[54.1,315.1,286.6,436.6],"p":276,"i":2,"sec":"die-zweite-gralsritter-in"},{"t":"sh","x":"<b>DER THRONSAAL</b>","sz":10.0,"box":[54.3,453.2,148.2,463.2],"p":276,"i":3,"sec":"die-zweite-gralsritter-in"},{"t":"ro","x":"Eure Haut kribbelt wie von unsichtbaren Nadelstichen oder von einem Feuer verbrannt, als ihr auf dem feuchten Beton ins letzte gebaute Stockwerk des Turms geht und euch durch den Schmerz zwängt. Über euch ragen die tragenden Säulen des unvollendeten Wolkenkratzers wie ausgestreckte Finger weit in den Himmel. Nach und nach nimmt die freiliegende Etage die Züge einer mondänen Gala an, auf der hochrangige Persönlichkeiten in Anzügen und Abendkleidern aus der Jahrhundertwende speisen und plaudern.","sz":9.0,"box":[62.4,467.3,283.8,605.9],"p":276,"i":4,"sec":"die-zweite-gralsritter-in"},{"t":"ro","x":"Kurz bevor Gold und Glitzer die Sicht ändert, erkennt ihr auf der gegenüberliegenden Seite einen dunklen Thron aus Betonplatten, von dem aus man die Stadt überblicken kann und auf dem eine alte, gebeugte Gestalt sitzt. Einen Moment später weicht die Gestalt einem großen, breitschultrigen Mann, den ihr wiedererkennt: Corbin Payne, der Mann, der die Stadt gebaut hat. Er erwartet euch.","sz":9.0,"box":[62.4,613.3,278.4,719.5],"p":276,"i":5,"sec":"die-zweite-gralsritter-in"},{"t":"p","x":"Corbin Payne empfängt seine Gäste in der obersten Etage des Wolkenkratzers, wo er eine lebendige Erinnerung – oder besser gesagt, eine Fantasie – der glamourösen Wohltätigkeitsgala geschaffen hat, an der er teilnehmen wollte, als die Schüsse auf dem roten Teppich fielen. Je nach Entwicklung des Gesprächs und seiner Gefühlslage kann er den Raum wieder in nackten Beton verwandeln. Details der Begegnung mit Payne s. <u>Corbin Payne höchstpersönlich</u> (s. S. 262).","sz":9.5,"box":[309.0,59.9,540.7,169.4],"p":276,"i":6,"sec":"die-zweite-gralsritter-in"},{"t":"p","x":"Wenn Payne das Haus verlassen hat, um seinen <u>Angriff auf die Stadt</u> zu inszenieren, bietet die Etage einen atemberaubenden Blick auf Zerstörung und Chaos.","sz":9.5,"box":[309.0,178.1,540.3,212.6],"p":276,"i":7,"sec":"die-zweite-gralsritter-in"},{"t":"card","x":"ANGRIFF AUF DIE STADT","sz":null,"k":"yellow","box":[299.2,220.9,482.7,243.9],"p":276,"i":8,"sec":"die-zweite-gralsritter-in"},{"t":"ro","x":"Plötzlich wird der Knoten in der Magengrube, der immer da ist, den man aber immer wegschiebt, so schlimm, dass ihr euch übergeben möchtet. Etwas Furchtbares geht vor sich, in euch, um euch herum, alle spüren es. Ihr hört einen Aufprall: ein Motorrad ist in eine Kneipe gerast. Einen Moment lang denkt ihr, das wäre es gewesen. Dann ein Schrei, und anderswo ein qualvolles Wimmern, und plötzlich riecht es verbrannt. Ein paar Blocks weiter hört ihr eine Explosion, und dann spürt ihr, wie der Boden unter euren Füßen bebt, Vorbote einer Katastrophe. Es ist so weit. Es hat begonnen. Payne ist hier.","sz":9.0,"box":[317.5,246.7,538.9,406.9],"p":276,"i":9,"sec":"die-zweite-gralsritter-in"},{"t":"p","x":"Corbin Payne verlässt sich auf seine Gralsritter:innen, die das Leid von ihm auf die Stadt umlenken. Da die Quelle seines Leidens legendär ist, lindert das seinen Schmerz kaum, hilft ihm aber, die Last zu tragen. Der Sieg über die ersten Gralsritter:in verschlimmert das Leiden des Avatars, aber er reißt sich zusammen und fährt fort, Elend zu verbreiten. Als das Team die Operation der zweiten Gralsritter:in angreift, kann der Avatar den aufgestauten Schmerz nicht mehr ertragen. Zum ersten Mal seit einem Jahrhundert verlässt er Corbin Tower und begibt sich an einen öffentlichen Ort, wo die Hölle losbricht.","sz":9.5,"box":[309.0,415.9,538.6,562.9],"p":276,"i":10,"sec":"die-zweite-gralsritter-in"},{"t":"p","x":"<b>Diese SL-Szene beschreibt Paynes katastrophalen Angriff auf die Stadt.</b> Verwende sie so, wie es deinen cineastischen Überlegungen entspricht. Sie kann stattfinden:","sz":9.5,"box":[309.0,571.6,539.8,618.5],"p":276,"i":11,"sec":"die-zweite-gralsritter-in"},{"t":"p","x":"• Bevor das Team Corbin Tower findet, was sie zum Handeln anspornt • Nach dem Besuch dort als Rache • Während des Besuchs als beunruhigende Vision dessen, was Payne entfesseln könnte usw.","sz":9.5,"box":[309.0,624.4,525.2,683.9],"p":276,"i":12,"sec":"die-zweite-gralsritter-in"}],"size":[595.276,841.89]},"277":{"tab":"","blocks":[{"t":"sh","x":"<b>CHAOS UND VERWIRRUNG IN DER INNEN- STADT</b>","sz":10.0,"box":[54.3,62.8,283.6,84.8],"p":277,"i":0,"sec":"die-zweite-gralsritter-in"},{"t":"p","x":"Cineastisch ausgedrückt ist diese Szene ein Katastrophenfilm. Zunächst sehen oder erfahren die SC von einer Reihe Ereignisse rund um das Stadtzentrum: Rauchschwaden aus einem PKW oder von einem Hubschrauberabsturz. Jemand springt von einem Gebäude. Massenpanik in der U-Bahn. Dies eskaliert schnell zur stadtweiten Katastrophe: eine Brücke stürzt ein. Ein Tankwagen explodiert. Hysterische Menschenmengen geraten außer Kontrolle.","sz":9.5,"box":[53.9,90.3,284.1,199.8],"p":277,"i":1,"sec":"die-zweite-gralsritter-in"},{"t":"p","x":"<b>Die Vorfälle haben ihren Ursprung in Payne, der in der Stadt herumläuft und seinem Elend freien Lauf lässt</b>, indem er entweder zufälligen Personen oder Gruppen Schmerzen zufügt, was die Menschen dazu bringt, den Schmerz auf katastrophale Weise zu versuchen zu beenden, oder voller Wut die Stadtlandschaft manipuliert (eine weitere Fähigkeit, die er besitzt, s. <u>Corbin Payne höchstpersönlich,</u> S. 262), was zu massiven Zerstörungen führt.","sz":9.5,"box":[53.9,208.6,281.0,318.0],"p":277,"i":2,"sec":"die-zweite-gralsritter-in"},{"t":"p","x":"Angesichts von Paynes außerordentlichen Kräften kann das Team wenig tun, um ihn zu stoppen. Die SC können Passant:innen vor Schaden bewahren, indem sie sie unterstützen, hindern, sich gegenseitig zu verletzen, vor Trümmern und Explosionen schützen und vor dem Schmerz der Umgebung abschirmen.","sz":9.5,"box":[53.9,326.7,278.6,398.7],"p":277,"i":3,"sec":"die-zweite-gralsritter-in"},{"t":"sh","x":"<b>DAS EPIZENTRUM</b>","sz":10.0,"box":[54.3,412.3,152.5,422.3],"p":277,"i":4,"sec":"die-zweite-gralsritter-in"},{"t":"p","x":"Inmitten all der Verwüstung, auf einem Platz in der Innenstadt, läuft Corbin Payne, barfuß, verzweifelt und unglücklich. Wenn das Team ihn findet, kann es versuchen, ihn anzusprechen, vor allem, wenn es noch nicht mit ihm interagiert hat. Weitere Informationen s. <u>Corbin Payne höchstpersönlich.</u>","sz":9.5,"box":[53.9,427.8,285.7,499.8],"p":277,"i":5,"sec":"die-zweite-gralsritter-in"}],"size":[595.276,841.89]},"278":{"tab":"","blocks":[],"size":[595.276,841.89]},"279":{"tab":"","blocks":[{"t":"h","x":"CORBIN PAYNE HÖCHSTPERSÖNLICH","sz":16.0,"box":[81.2,74.1,224.3,107.1],"p":279,"i":0,"skip":true,"sec":"corbin-payne-hoechstpersoenlich"},{"t":"p","x":"Wenn das Team das erste Mal auf Payne trifft, wissen die SC noch nichts vom Gral und haben keine Möglichkeit, den Baulöwen zu töten oder zu heilen. Diese Szene dient dazu, sie zu beschämen, indem er ihren geheimen Schmerz dazu nutzt, einige von ihnen zu Schurk:innen zu machen, aber auch, um die Hinweise zu enthüllen, die ihnen noch fehlen:","sz":9.5,"box":[53.9,111.1,279.0,195.6],"p":279,"i":1,"sec":"corbin-payne-hoechstpersoenlich"},{"t":"card","x":"Corbin Payne ist nicht böse. Er ist ein Mann, der mehr Schmerz leidet, als er ertragen kann.","sz":null,"k":"yellow","box":[54.1,206.5,286.6,240.2],"p":279,"i":2,"sec":"corbin-payne-hoechstpersoenlich"},{"t":"card","x":"<b>Payne besitzt den Gral</b>, ein Relikt von unermesslicher Macht, das ihn vor dem Tod bewahrt, doch er kann ihn nicht benutzen, um sich zu heilen.","sz":null,"k":"yellow","box":[54.1,249.4,286.6,308.2],"p":279,"i":3,"sec":"corbin-payne-hoechstpersoenlich"},{"t":"card","x":"<b>Die Wurzel der Misere liegt in der Erkenntnis, dass in der Stadt nichts „echt“ ist</b> – alles besteht aus Nebel, nichts hat wirklich Bedeutung. Dieser gefühlte Bedeutungsverlust ließ ihn als Fischerkönig erwachen.","sz":null,"k":"yellow","box":[54.1,317.4,286.6,388.5],"p":279,"i":4,"sec":"corbin-payne-hoechstpersoenlich"},{"t":"card","x":"Alle fehlenden Hinweise aus Akt 1 und 2.","sz":null,"k":"yellow","box":[54.1,398.0,286.6,419.0],"p":279,"i":5,"sec":"corbin-payne-hoechstpersoenlich"},{"t":"h","x":"ERSCHEINUNGSBILD","sz":16.0,"box":[53.9,438.9,189.8,454.9],"p":279,"i":6,"skip":true,"sec":"erscheinungsbild"},{"t":"p","x":"Als Avatar des Fischerkönigs (der seine Wunde gut zu verbergen weiß) kann Corbin Payne in fast jeder beliebigen Gestalt erscheinen, wobei er folgende bevorzugt:","sz":9.5,"box":[53.9,458.8,285.5,493.3],"p":279,"i":7,"sec":"erscheinungsbild"},{"t":"p","x":"In seiner <b>Form aus guten Tagen</b> ist Payne ein gesunder, gut gebauter Mann Ende vierzig in einem flotten Anzug und mit einer Frisur aus der Jahrhundertwende, der Selbstvertrauen und Charisma ausstrahlt, witzig ist, herzlich lacht und alle unterhält. Man spürt die Dissonanz zwischen dieser Fassade und seinem wahren Gemütszustand. Er kann diese Ironie bis zum Erbrechen verstärken.","sz":9.5,"box":[53.9,502.0,284.1,599.0],"p":279,"i":8,"sec":"erscheinungsbild"},{"t":"p","x":"In seiner <b>Gestalt als Clochard</b> ist Payne derselbe Mann, nur Mitte siebzig, sein Anzug zerschlissen, der Körper kaputt, mit müdem Geist, das Haar zerzaust und schmutzig. Payne ist barfuß. Er wirkt mutlos und unkonzentriert, verliert oft den Faden, als leide er an einer degenerativen Krankheit. Er trägt diese Gestalt, wenn er in ruhiger Stimmung oder allein ist (z. B. beim Fischen).","sz":9.5,"box":[53.9,607.7,284.3,704.7],"p":279,"i":9,"sec":"erscheinungsbild"},{"t":"p","x":"In seiner <b>Gestalt als Avatar der Agonie</b> ist Payne ein Anblick, den nur wenige ertragen können. Er trägt seine Wunde offen, aber man nimmt sie nicht richtig wahr. Stattdessen überflutet ein unerträglicher Strom des Elends die Umgebung mit sensorischen Wellen der","sz":9.5,"box":[53.9,713.3,283.3,772.8],"p":279,"i":10,"sec":"erscheinungsbild"},{"t":"p","x":"Pein, während er flucht, spuckt und um sich tritt. Alle Betrachter:innen sehen eine andere Erscheinung, die auf ihrem eigenen geheimen Schmerz beruht, wobei die <t>geheilten</t> Paynes wahre Wunde sehen: den Mangel an Substanz und Bedeutung.","sz":9.5,"box":[309.1,59.9,534.6,119.4],"p":279,"i":11,"sec":"erscheinungsbild"},{"t":"p","x":"In welcher Form Payne auftritt, <b>der Gral</b> folgt ihm überall hin und erscheint jedes Mal in einem anderen Gefäß, vom Kelch bis zum Müllcontainer. Wenn niemand den Gral bewegt, verschwindet er und erscheint in der Nähe Paynes, als wolle er seine Bewegungsrichtung vorhersagen. Im Gegensatz zu Payne strahlt er friedfertige Stille aus.","sz":9.5,"box":[309.1,128.1,537.1,212.6],"p":279,"i":12,"sec":"erscheinungsbild"},{"t":"h","x":"KRÄFTE","sz":16.0,"box":[309.1,228.3,360.5,244.3],"p":279,"i":13,"skip":true,"sec":"kraefte"},{"t":"p","x":"Wie alle Avatare ist Payne nicht als Gegner gedacht, sondern als interessante Begegnung für das Team. Er ist unbesiegbar: Das Gelände der Stadt schirmt ihn ab. Er kann jede Menge Schmerz umleiten. Selbst wenn er stirbt, belebt ihn der Gral wieder usw. Und er kann einen Stufe-5-Zustand als Einmischung und einen Stufe-6-Zustand als weiche Aktion verursachen.","sz":9.5,"box":[309.1,248.2,537.9,332.7],"p":279,"i":14,"sec":"kraefte"},{"t":"p","x":"Als <b>Avatar des Leidens</b> kann Corbin Payne:","sz":9.5,"box":[309.1,341.4,495.3,351.0],"p":279,"i":15,"sec":"kraefte"},{"t":"p","x":"• Jede Form von Schmerz in der Stadt spüren. Er ist sich aller Bewohner:innen, ihres Geisteszustandes, schmerzhaften Erinnerungen und Geheimnisse bewusst.","sz":9.5,"box":[309.1,362.4,531.9,409.4],"p":279,"i":16,"sec":"kraefte"},{"t":"p","x":"• Einer beliebigen Anzahl von Menschen eine Empfindung oder Gefühl aus dem Spektrum des Schmerzes zufügen und auf die Opfer abstimmen, um Angst, Wut, Scham, Verzweiflung usw. hervorzurufen.","sz":9.5,"box":[309.1,418.0,539.3,465.0],"p":279,"i":17,"sec":"kraefte"},{"t":"p","x":"• Mit einem Wort, einer Geste, Mimik oder Vision usw. eine <t>Nimmer heilende Wunde</t> mit einer Stufe verursachen, die der des Ziels bei verwundet entspricht. (Er wird nicht mehr als ein oder zwei Menschen pro Szene so zur Gralsritter:in schlagen, s. u.)","sz":9.5,"box":[309.1,473.7,539.4,533.2],"p":279,"i":18,"sec":"kraefte"},{"t":"h","x":"GEHEILTE CHARAKTERE","sz":11.0,"box":[320.3,562.8,431.3,573.8],"p":279,"i":19,"sec":"kraefte"},{"t":"p","x":"Ein <t>geheilter</t> Charakter kann gegen Payne <b>Sich der Gefahr stellen</b> einschließlich der <t>Nimmer heilenden Wunde</t>. Wenn ein <t>geheilter</t> SC die <t>Nimmer heilende Wunde</t> mit einer Stufe unter 6 erhält, kann er sie wie jeden nicht-permanenten Zustand reduzieren.","sz":9.0,"box":[320.3,580.9,522.7,649.9],"p":279,"i":20,"sec":"kraefte"},{"t":"p","x":"Eine teilweise <t>Nimmer heilende Wunde</t> zwingt den SC, sich selbst und anderen zu schaden, aber der Charakter verliert Themen (wie unter Die Nimmer heilende Wunde, S. 18, beschrieben) erst, wenn der Zustand Stufe 6 erreicht.","sz":9.0,"box":[320.3,658.5,518.6,715.5],"p":279,"i":21,"sec":"kraefte"},{"t":"p","x":"Unabhängig von der Stufe können <t>geheilte</t> SC versuchen, den behinderndem Effekt eine Szene lang zu widerstehen, indem sie <b>Ein Risiko eingehen</b>.","sz":9.0,"box":[320.3,724.2,529.9,757.2],"p":279,"i":22,"sec":"kraefte"}],"size":[595.276,841.89]},"280":{"tab":"","blocks":[{"t":"p","x":"• Die Avatarschaft von jemandem in seiner Gegenwart beenden oder jemanden als Riss erwecken (einschließlich derer, die das Jenseitige leugnen), indem er ihren geheimen Schmerz verstärkt.","sz":9.5,"box":[53.9,59.9,283.7,106.9],"p":280,"i":0,"sec":"kraefte"},{"t":"p","x":"Als <b>König, der die Stadt ist</b>, beherrscht Payne sie absolut: Er kann jede Straße, jedes Gebäude, Block oder Viertel formen, und dabei die Gesetze der Physik ignorieren. Er kann jemanden, der ihn verfolgt, vor einen endlosen Betonstreifen setzen oder den Weg mit einer Straße auf der anderen Seite der Stadt verbinden, so dass die Person dort festsitzt. Er kann alte, abgerissene Gebäude mitten auf einem Platz wieder erstehen lassen oder Wolkenkratzer plattmachen und alle darin befindlichen Personen töten. Die Fähigkeit ist überall in der Stadt gleich stark und nimmt nur außerhalb ab.","sz":9.5,"box":[53.9,115.6,285.9,250.1],"p":280,"i":1,"sec":"kraefte"},{"t":"p","x":"Als <b>Träger des Grals</b> ist Payne immun gegen Tod, Verderbnis, Krankheit, Gift und andere schädliche Einflüsse. Der Gral hält schützt ihn vor Schaden, aber da er seine Aufmerksamkeit dem Mythos, dem Schmerz, widmet, ist er der unfähigste Mensch der Stadt, wenn es darum geht, den Gral zu aktivieren.","sz":9.5,"box":[53.9,258.8,284.0,330.8],"p":280,"i":2,"sec":"kraefte"},{"t":"h","x":"DIE UNTERHALTUNG","sz":16.0,"box":[53.9,346.4,185.5,362.4],"p":280,"i":3,"skip":true,"sec":"die-unterhaltung"},{"t":"p","x":"Im Gespräch mit den SC ist Payne ein zerrissener, erschöpfter Mann, der im besten Fall melancholisch und die meiste Zeit über geistesgestört wirkt. Auch wenn sein Gewissen ihm sagt, er solle seinen Schmerz nicht auf andere abwälzen, tut er es am Ende doch, und das schon so lange, dass er kaum etwas anderes kennt.","sz":9.5,"box":[53.9,366.4,282.8,438.4],"p":280,"i":4,"sec":"die-unterhaltung"},{"t":"p","x":"Er ist so voll mit Elend, dass ihn alles dazu bringt, die Stimmung zu ändern (wütend, resigniert, verbittert, traurig usw.), die Gestalt zu wechseln oder einen Wutanfall zu bekommen, und Schmerzen zuzufügen.","sz":9.5,"box":[53.9,447.0,281.0,494.0],"p":280,"i":5,"sec":"die-unterhaltung"},{"t":"p","x":"Payne wird versuchen, die SC nacheinander mit der <t>Nimmer heilenden Wunde</t> zu Ritter:innen zu schlagen, wobei er den Augenblick genießt und sich Zeit nimmt, ihren geheimen Schmerz zu analysieren, den er instinktiv fühlt. Nachdem er ein oder zwei SC zu Ritter:innen geschlagen hat, hört er auf und überlässt es dem Team, sich um die Nachwirkungen zu kümmern.","sz":9.5,"box":[53.9,502.7,286.5,587.2],"p":280,"i":6,"sec":"die-unterhaltung"},{"t":"h","x":"DER GRAL","sz":16.0,"box":[53.9,602.9,117.9,618.9],"p":280,"i":7,"skip":true,"sec":"der-gral-3"},{"t":"p","x":"Payne wird jeden SC, der nicht vollständig <t>geheilt</t> ist, erlauben, auf den Gral zuzugreifen und zu versuchen, ihn zu aktivieren, mit Hoffnung, aber wohl wissend, dass es nach hinten losgehen wird (s. S. 265).","sz":9.5,"box":[53.9,622.8,279.0,669.8],"p":280,"i":8,"sec":"der-gral-3"},{"t":"p","x":"Der Gral, der Payne als Träger auserkoren hat, verschwindet, wenn ihn jemand nehmen will, und kehrt zu Payne zurück. Keine Macht der Stadt kann ihn daran hindern. Die Berührung des Grals birgt wichtige Hinweise für den Fall <u>(Nachforschungen über den Gral).</u>","sz":9.5,"box":[53.9,678.5,286.5,738.0],"p":280,"i":9,"sec":"der-gral-3"},{"t":"h","x":"NACHFORSCHUNGEN ÜBER DEN GRAL","sz":16.0,"box":[333.9,68.9,512.9,101.9],"p":280,"i":10,"skip":true,"sec":"nachforschungen-ueber-den-gral"},{"t":"p","x":"Sobald der Gral enthüllt ist, will das Team vielleicht mehr über ihn erfahren. Die Begegnung mit Payne bietet eine kurze Gelegenheit, ihn zu untersuchen. Wenn der Gral in den <u>Corbin Tower</u> zurückkehrt, verbergen ihn die Enklave und der Nebel. Man kann ihn nicht aus der Ferne untersuchen, so dass nur spekulative Forschung möglich ist. Das Team kann versuchen:","sz":9.5,"box":[309.0,105.8,539.8,190.3],"p":280,"i":11,"sec":"nachforschungen-ueber-den-gral"},{"t":"p","x":"• Den Gral zu untersuchen • Mit dem Gral zu kommunizieren • In seiner Gegenwart <b>Jenseits des Nebels</b> zu schauen • Über den Gral zu meditieren, um eine mystische Vision von ihm zu erlangen, indem die SC entsprechende Stärken verwenden • Seltene mystische Manuskripte oder schwer zugängliche Mystiker:innen zu befragen • Die Eigenschaften des Gralswassers aus der mystischen Ebene zu studieren (s. S. 149 und 171)","sz":9.5,"box":[309.0,196.1,540.3,318.1],"p":280,"i":12,"sec":"nachforschungen-ueber-den-gral"},{"t":"card","x":"Der Legende nach kann der Gral, der je nach Sagenkreis manchmal auch ein Zauberkessel ist, jede Wunde heilen und sogar Tote wieder erwecken, aber es gibt nur wenige Informationen darüber, wie man das tut.","sz":null,"k":"yellow","box":[309.3,327.7,541.7,398.9],"p":280,"i":13,"sec":"nachforschungen-ueber-den-gral"},{"t":"card","x":"Der Gral ist viel mehr als ein Heilwerkzeug. Er ist ein Tor in eine große, ruhige Leere, ein Feld unendlichen Potenzials, das selbst jenseits der Mythen existiert, wo alles eins ist. <b>Wer die Macht des Grals besitzt, dem ist alles möglich.</b>","sz":null,"k":"yellow","box":[309.3,408.1,541.7,491.9],"p":280,"i":14,"sec":"nachforschungen-ueber-den-gral"},{"t":"card","x":"Als Tor zu unendlichen Möglichkeiten kann der Gral sogar Risse erwecken.","sz":null,"k":"yellow","box":[309.3,501.1,541.7,535.1],"p":280,"i":15,"sec":"nachforschungen-ueber-den-gral"},{"t":"card","x":"Der Gral gibt seine Macht nicht an Menschen weiter, die noch in der Mühsal des Irdischen gefangen sind. Stattdessen spiegelt er ihnen ihr Leiden, damit sie erwachen können.","sz":null,"k":"yellow","box":[309.3,544.0,541.7,603.1],"p":280,"i":16,"sec":"nachforschungen-ueber-den-gral"},{"t":"card","x":"Der Gral gibt sich niemanden zu erkennen, der nie in der Mühsal des Irdischen gefangen war, wie Beschwörungen oder Wesen, die dem Leiden entkommen sind. Nur die, die Verwundet und geheilt wurden, können das Geheimnis des Grals erkennen.","sz":null,"k":"yellow","box":[309.3,612.3,541.7,696.1],"p":280,"i":17,"sec":"nachforschungen-ueber-den-gral"}],"size":[595.276,841.89]},"281":{"tab":"","blocks":[{"t":"h","x":"AKT 3","sz":23.0,"box":[53.9,63.4,110.2,86.4],"p":281,"i":0,"skip":true,"sec":"akt-3"},{"t":"p","x":"Akt 3 beginnt, wenn das Team den Namen Rio Beaumont erfährt und sie als die Gralsritterin identifiziert, die verschwunden ist und in die Payne seine Hoffnungen setzt. Als abschließender Akt der Kampagne gibt er den SC die Chance, all die Erfahrungen, die sie im Laufe der Serie gesammelt haben, in die Tat umzusetzen – im Guten wie im Schlechten.","sz":13.0,"box":[53.9,94.3,276.6,237.8],"p":281,"i":1,"sec":"akt-3"},{"t":"p","x":"Bevor du diesen letzten Akt in Angriff nimmst, tritt einen Schritt zurück und betrachte die Reise, die die Protagonist:innen von den Aufhängern des ersten Falles bis zu diesem Punkt gemacht haben. Wen haben sie beschützt? Wen haben sie zerbrochen? Wen haben sie im Stich gelassen? Wem konnten sie nicht helfen? Die ergreifendsten Emotionen und denkwürdigsten NSC können noch einmal auftreten, um am Abschluss der Kampagne teilzunehmen.","sz":9.5,"box":[53.9,248.4,284.8,357.9],"p":281,"i":2,"sec":"akt-3"},{"t":"p","x":"Überlege, <i>was das Team geworden ist</i> und was mit dem geheimen Schmerz seiner Mitglieder geschehen ist. Haben sich eines oder mehrere mit ihrem Schmerz abgefunden, eine Erkenntnis, die sie verändert hat? Sind sie <t>geheilt</t>? Haben einige von ihnen ihrer Wunde nur wenig Aufmerksamkeit geschenkt, gerade genug, um zurechtzukommen? Gab es unter ihnen wahre Antihelden, unheilbar und zerrissen bis zum Ende?","sz":9.5,"box":[53.9,366.5,285.7,463.5],"p":281,"i":3,"sec":"akt-3"},{"t":"p","x":"Entscheide auf dieser Grundlage, welche Art von Ende du dir für die Serie wünschst.","sz":9.5,"box":[53.9,472.2,281.7,494.2],"p":281,"i":4,"sec":"akt-3"},{"t":"p","x":"• Wenn das Team Turbulenzen und harte Entscheidungen im Kampf gegen die Gralsritter:innen und bezüglich der Heilung ihres geheimen Schmerzes hinter sich hat, ist vielleicht ein ruhiges Ende am besten geeignet. Überspringe <u>Was sein muss</u> und konzentriere dich auf Corbin Paynes Heilung.","sz":9.5,"box":[53.9,505.7,272.9,577.7],"p":281,"i":5,"sec":"akt-3"},{"t":"p","x":"• Wenn die SC noch mit Dämon:innen ringen und du das Gefühl hast, dass harte Entscheidungen nötig sind, um die Kampagne zu beenden oder wenn du ein düsteres Ende möchtest, kannst du <u>Was sein muss</u> spielen, um zynische, rachsüchtige oder pragmatische Charaktere zu kaltherzigem Handel zu verleiten.","sz":9.5,"box":[53.9,586.4,283.6,670.9],"p":281,"i":6,"sec":"akt-3"},{"t":"h","x":"DIE DRITTE GRALSRITTER:IN","sz":16.0,"box":[79.7,684.7,266.2,700.7],"p":281,"i":7,"skip":true,"sec":"die-dritte-gralsritter-in"},{"t":"p","x":"Die dritte Gralsritter:in ähnelt der ersten und zweiten, aber sie kennt (oder erinnert sich, im Falle Vince Beaumonts) an ein wichtiges Detail: Rio.","sz":9.5,"box":[53.9,704.6,285.7,739.1],"p":281,"i":8,"sec":"die-dritte-gralsritter-in"},{"t":"card","x":"Wie alle Gralsritter:innen hatte auch die dritte ein persönliches Verhältnis zu Corbin Payne und erhielt die Nimmer heilende Wunde (s. S. <u>Die erste Gralsritter:in,</u> S. 265).","sz":null,"k":"yellow","box":[309.3,54.1,541.7,112.9],"p":281,"i":9,"sec":"die-dritte-gralsritter-in"},{"t":"card","x":"Die dritte Gralsritter:in berichtet, Payne sagte, <b>dass Rio Beaumont sein Parzival ist, die letzte Hoffnung</b>. Keiner hat Rio gesehen, seit sie vor Jahrzehnten Paynes Wohnung verlassen hat, verloren und verwirrt. <b>Dennoch glaubt die dritte Ritter:in, dass Rio der Schlüssel ist.</b>","sz":null,"k":"yellow","box":[309.3,122.1,541.7,205.9],"p":281,"i":10,"sec":"die-dritte-gralsritter-in"},{"t":"card","x":"Die dritte Gralsritter:in vermutet, dass Rio eine weitere (vierte) Gralsritter:in ist, dass auch sie versucht hat, Corbin Payne zu heilen und dabei gescheitert ist, dass aber Payne aus irgendeinem Grund noch an sie glaubt.","sz":null,"k":"yellow","box":[309.3,215.1,541.7,286.6],"p":281,"i":11,"sec":"die-dritte-gralsritter-in"},{"t":"h","x":"PARKSIDE CAFE","sz":16.0,"box":[334.8,305.6,437.2,321.6],"p":281,"i":12,"skip":true,"sec":"parkside-cafe"},{"t":"ro","x":"Ihr findet Rio in einem kleinen Café im Parterre ihres Wohnhauses, gegenüber dem Park. Zuerst sieht man eine junge Frau, die hoffnungsvoll in den Horizont blickt, dieselbe naive Frau, die ihr in den Visionen von Paynes Erinnerungen gesehen habt. Doch dann tritt für einen Moment ein Passant dazwischen, und sie ist plötzlich eine ältere Dame mit einem Gesichtsausdruck tiefen Friedens. Eure Blicke treffen sich, und ihr wisst, dass ihr die Person gefunden habt, die ihr gesucht habt: Parzival.","sz":9.0,"box":[317.5,323.9,538.9,462.5],"p":281,"i":13,"sec":"parkside-cafe"},{"t":"sh","x":"<b>RIO FINDEN</b>","sz":10.0,"box":[309.4,476.5,374.7,486.5],"p":281,"i":14,"sec":"parkside-cafe"},{"t":"p","x":"Da Rio Beaumont das <b>Jenseitige leugnet</b>, sich dem Nebel hingibt und sich vor allen versteckt, kann man sie nur mit ganz gewöhnlichen Mitteln aufspüren. <b>Sobald das Team ihren Namen kennt, kann es sie einfach im Telefonbuch oder im Internet finden.</b>","sz":9.5,"box":[309.0,492.1,531.6,551.7],"p":281,"i":15,"sec":"parkside-cafe"},{"t":"card","x":"<b>Wenn du die <i>Stadtkarte</i> mit Galahads Dolch verwendest</b>, befinden sich Rios Wohnung und ihr Lieblingscafé dort, wo sich die Linien von Corbin Payne und den anderen Gralsrittern kreuzen, in der Mitte der Parierstange.","sz":null,"k":"yellow","box":[309.3,563.0,541.7,634.2],"p":281,"i":16,"sec":"parkside-cafe"},{"t":"sh","x":"<b>DAS TREFFEN MIT RIO</b>","sz":10.0,"box":[309.4,648.1,431.9,658.1],"p":281,"i":17,"sec":"parkside-cafe"},{"t":"p","x":"Rio ist eine majestätische, betagte Dame, fast 100 Jahre alt, aber man sieht es ihr nicht an. Mit hoch erhobenem Kopf strahlt sie Ruhe, Wärme und Freiheit von Sorgen aus. Sie hat ihren Frieden gefunden und sieht die wahre Natur von allem, was sie umgibt. Aus dem Blickwinkel ihres <t>geheilten</t> Geistes (nimm an, sie sei auf Stufe 5 oder 6) sind alle Gegensätze eins: Mythos und Nebel, Gut und Böse, Schmerz und Heilung.","sz":9.5,"box":[309.0,663.7,537.6,760.7],"p":281,"i":18,"sec":"parkside-cafe"}],"size":[595.276,841.89]},"282":{"tab":"","blocks":[{"t":"card","x":"<b>Rio berichtet von ihrer Vergangenheit.</b> Als sie das erste Mal in den Gral sah, offenbarte er ihr, dass sie nicht wirklich wusste, wer sie war, und wenn sie Licht in die Geheimnisse anderer bringen wolle, müsse sie sich zunächst selbst auf den Weg machen. Da beschloss sie, Schläferin zu werden, die Welt der Risse hinter sich zu lassen, und einzuschlafen, um zu erwachen. Nach und nach, Jahr für Jahr, öffnete sie sich dieser Erkenntnis.","sz":null,"k":"yellow","box":[54.1,54.1,286.6,188.1],"p":282,"i":0,"sec":"parkside-cafe"},{"t":"card","x":"<b>Rio berichtet, was sie über den Gral weiß.</b> Er ist kein Gefäß, sondern ein Muster dafür, wie man selbst ein Gefäß werden kann. Um seine Kraft zu aktivieren, muss man zum Gral werden, voller Aufmerksamkeit, voller Bewusstsein. Um die Kraft des Grals zu erschließen, muss man sich ganz und gar kennen. <b>Dann genügt es, still zu sein und zu lauschen, um ihn zu aktivieren.</b> Doch Rio weiß nicht, wie viel Selbsterkenntnis es braucht. Niemand kann wissen, ob er bereit ist, solange er den Gral nicht in Händen hält und in ihn hineinschaut.","sz":null,"k":"yellow","box":[54.1,197.3,286.6,356.0],"p":282,"i":1,"sec":"parkside-cafe"},{"t":"card","x":"(Falls die SC es übersehen haben:) <b>Rio weiß, dass Payne auf der <u>Abwrackwerft</u> fischen geht.</b>","sz":null,"k":"yellow","box":[54.1,365.2,286.6,411.6],"p":282,"i":2,"sec":"parkside-cafe"},{"t":"p","x":"Mit diesem neuen Verständnis des Grals sind die SC vielleicht bereit, sich Payne ein letztes Mal zu stellen. Einige wollen ihn vielleicht heilen, während andere erkennen, dass die Macht über den Gral bedeuten könnte, dass der alte, elende König endlich sterben kann.","sz":9.5,"box":[309.0,59.9,540.0,119.4],"p":282,"i":3,"sec":"parkside-cafe"},{"t":"p","x":"Am Ende der Szene steht Rio vor der Entscheidung, ob sie die Verleugnung des Jenseitigen aufgeben und sich ihrem eigenen Mythos wieder öffnen soll. Als <t>geheilte</t> Schläferin trifft sie diese Entscheidung bewusst. Man kann sich nicht gegen ihren Willen dazu bringen, die Existenz des Legendären anzuerkennen.","sz":9.5,"box":[309.0,128.1,537.9,200.1],"p":282,"i":4,"sec":"parkside-cafe"},{"t":"p","x":"Wenn du ein dramatisches Ass im Ärmel willst, weigert sie sich, mit dem Argument, sie sei noch nicht bereit. Wenn das Team versucht, den Gral zu aktivieren, und scheitert, taucht im letzten Moment die strahlende Gestalt einer jungen Frau auf, um den Tag zu retten: Rio, verwandelt durch die Macht ihres Mythos Parzival.","sz":9.5,"box":[309.0,208.8,541.7,280.8],"p":282,"i":5,"sec":"parkside-cafe"},{"t":"h","x":"WAS SEIN MUSS","sz":16.0,"box":[333.1,297.4,441.6,313.4],"p":282,"i":6,"skip":true,"sec":"was-sein-muss"},{"t":"ro","x":"Neonlicht knistert über der schmutzigen Seitengasse im Industriegebiet, in der ihr euren Kontakt treffen sollt. Ihr trommelt nervös mit den Fingern auf eure Oberschenkel, während ihr im aufziehenden Nebel wartet, und werft ab und zu einen Blick auf die Scheinwerfer der vorbeifahrenden Autos. Nach einer Weile könnt ihr die vage Gestalt eines Mannes in Regenmantel und Filzhut erkennen, der aus dem Nebel ins schummrige Licht tritt. Er nähert sich, zündet sich eine Zigarette an,","sz":9.0,"box":[317.5,315.8,538.9,443.6],"p":282,"i":7,"sec":"was-sein-muss"}],"size":[595.276,841.89]},"283":{"tab":"","blocks":[{"t":"ro","x":"nimmt einen Zug und bläst lang den Rauch aus. „Schön, dass Sie gekommen sind.“ Es folgt ein langes Schweigen. „Wir haben eine seltene Gelegenheit. Ich denke, Sie wissen, was zu tun ist.“","sz":9.0,"box":[62.4,58.4,278.4,110.6],"p":283,"i":0,"sec":"was-sein-muss"},{"t":"p","x":"Einige der Protagonist:innen meinen vielleicht, man könne oder solle Corbin Payne nicht heilen, sondern sollte ihn erlösen oder in eine Hölle stürzen, aus der er niemals entkommen kann. Sie sind nicht allein. Viele der wichtigen Akteur:innen der Stadt teilen diese Ansicht. Nach dem Gespräch im <u>Parkside Cafe</u> bietet die Möglichkeit, die Macht des Grals zu „kontrollieren“ (durch Rio oder einen <t>geheilten</t> SC), eine Gelegenheit, Payne an seiner verwundbarsten Stelle zu treffen und die Stadt endgültig von ihm zu befreien. Die wichtigen Akteur:innen der Stadt sind sich dessen bewusst und wenden sich an die Mitglieder des Teams, die am ehesten zur Kooperation bereit sind, mit dem Angebot, ihnen zu helfen zu tun, was getan werden muss.","sz":9.5,"box":[53.9,119.6,285.4,291.6],"p":283,"i":1,"sec":"was-sein-muss"},{"t":"p","x":"Die besten Kandidat:innen sind die Torwächter:innen (obwohl du auch einen Avatar, Gralsritter:in oder ein beliebiges Opfer Paynes einsetzen kannst). Nachdem sie gesehen haben, was Payne der Stadt antut, wollen sie ihr unheiliges Abkommen mit ihm brechen, um sicherzustellen, dass er beim nächsten Wutanfall nicht gleich Schwärme von Schläfer:innen erweckt. Die Torwächter:innen machen ein Angebot: Sie werden die Mittel zur Verfügung stellen, um Payne zu vernichten, wenn die SC den Gral aktivieren und den Plan ausführen. Wenn es zu einer Einigung kommt, bringen die Torwächter:innen <b>Manannans Mantel</b> zum Vorschein, ein Tuch aus sich windendem Nebel, das man wie Stoff anfassen kann. Der Umhang transportiert seine Träger:in in den tiefen Nebel und in die JVA Thorne (Tartaros, der Abgrund, in dem die griechischen Titanen gefangen sind). Leider schützt der Gral Payne vor dem Nebel, und hier kommen die SC ins Spiel.","sz":9.5,"box":[53.9,300.3,286.2,522.3],"p":283,"i":2,"sec":"was-sein-muss"},{"t":"p","x":"Die SC müssen den Gral nutzen (was eine <t>geheilte</t> Person erfordert), den Avatar unschädlich machen und in den Umhang hüllen. Alternativ kann der Umhang, sobald der Gral aktiv ist, diesen wegschaffen, wodurch Payne anfällig für Schaden und Tod wird.","sz":9.5,"box":[53.9,531.0,283.8,590.5],"p":283,"i":3,"sec":"was-sein-muss"},{"t":"h","x":"ABWRACKWERFT","sz":16.0,"box":[79.7,610.1,194.5,626.1],"p":283,"i":4,"skip":true,"sec":"abwrackwerft"},{"t":"ro","x":"Massive rostige Skelette gesunkener Schiffe ragen aus dem Wasser. Möwen schreien hoch am Himmel, kreisen in den blassen Sonnenstrahlen über dem salzigen Seenebel. Corbin Payne, der Mann, der die Stadt ist, sitzt in einem armseligen Boot, das auf den Wellen schaukelt, und angelt. Langsam bückt er sich, um einen kleinen Fisch vom Haken zu nehmen, ihn gegen die Bordwand zu schlagen und leblos in einen Eimer zu werfen. Einen Augenblick später springt der Fisch aus dem Eimer zurück ins weite blaue Meer.","sz":9.0,"box":[62.4,625.5,283.8,764.1],"p":283,"i":5,"sec":"abwrackwerft"},{"t":"p","x":"In der Schlussszene fischt Payne friedlich im Hafen, vor der Kulisse gekenterter Schiffe. Er ist seltsam ruhig, vielleicht, weil er sich mit seinem das Hobby befasst, wegen seines <u>Angriffs auf die Stadt,</u> des Falls der Gralsritter:innen oder aufgrund einer Vorahnung dessen, was kommen wird. Das ist die Gelegenheit, ihn und durch ihn den Gral körperlich und seelisch zu erreichen. Wenn die Szene beginnt, ist er nicht mehr das Monster aus dem zweiten Akt, sondern ein müder, gebrochener Mann, der eine unvorstellbare Last trägt, und doch immer noch der Avatar des Fischerkönigs.","sz":9.5,"box":[309.0,59.9,537.1,194.4],"p":283,"i":6,"sec":"abwrackwerft"},{"t":"p","x":"Wähle aus, wer anwesend ist. Ist Corbin Payne allein? Oder taucht vielleicht die gesamte Stadt am Ufer auf, um am Schmerz und der Heilung des Fischerkönigs teilzuhaben? Vielleicht sind wichtige NSC aus der Kampagne in dieser Szene dort oder greifen sogar ein.","sz":9.5,"box":[309.0,203.1,536.4,262.6],"p":283,"i":7,"sec":"abwrackwerft"},{"t":"p","x":"<b>Wenn es den SC gelingt, die Macht des Grals (s. S. 265) zu nutzen und Payne zu heilen, ist dies ein heiliger Augenblick der Harmonie und Ganzheit.</b> Je nach Stil und Stimmung können die Spezialeffekte hier von einem minimalistischen, aber schönen Moment der Stille über einen klassischen Blick auf eine Lichtsäule, die durch die Wolken über der Bucht scheint, bis hin zur kosmisch-transzendentalen Erfahrung beim Kontakt mit der Quelle aller Dinge reichen. Payne stirbt friedlich oder beendet sein Avatar-Dasein, wird zum Schläfer und überlässt den SC die Entscheidung, was weiter mit ihm geschehen soll. Alternativ kann sein Schicksal auch unklar und rätselhaft bleiben.","sz":9.5,"box":[309.0,271.4,541.4,430.8],"p":283,"i":8,"sec":"abwrackwerft"},{"t":"p","x":"<b>Wenn die SC im Augenblick der Verwundbarkeit den Gral nutzen, um zu versuchen, Payne zu töten oder ihn in die JVA Thorne zu verbannen</b>, kann es zu einem Kampf auf Avatar-Ebene kommen. Ohne den Gral und die Stadt, die er manipulieren kann, ist der Avatar stark geschwächt und muss sich auf die Schmerzen verlassen. Da viel auf dem Spiel steht, solltest du dich nicht mit grundlegenden Aktionen aufhalten, sondern Handlungen narrativ oder höchstens mit <b>Jetzt reicht’s!</b> abwickeln. Wenn Payne die SC besiegt, können einige oder alle von ihnen seine neuen Gralsritter:innen werden. Wenn die SC Payne besiegen, ist ein Preis zu zahlen, den niemand bis zum Augenblick der Wahrheit voraussehen konnte: Schmerz und Gnade, Payne und der Gral sind zwei Seiten derselben Medaille. Wenn die eine schwindet, geht auch die andere. Einen im Nebel zu begraben würde die Stadt in einen Tiefschlaf versetzen, und die Kraft des Erwachens wäre für immer verloren. Payne zu töten, ehe er geheilt ist, würde zum selben Ergebnis führen.","sz":9.5,"box":[309.0,439.6,541.7,686.4],"p":283,"i":9,"sec":"abwrackwerft"},{"t":"p","x":"<b>Wenn die Teammitglieder gegensätzliche Standpunkte vertreten</b>, lass sie das mit Worten oder Fäusten austragen und schau, was passiert.","sz":9.5,"box":[309.0,695.2,534.4,729.6],"p":283,"i":10,"sec":"abwrackwerft"},{"t":"p","x":"Um es mit den Worten eines großen Spieleentwicklers zu sagen: Wir beneiden dich um deine Erkenntnis.","sz":9.5,"box":[309.0,738.3,536.7,760.3],"p":283,"i":11,"sec":"abwrackwerft"}],"size":[595.276,841.89]},"284":{"tab":"","blocks":[{"t":"card","x":"<u>ABSPANN</u>","sz":null,"k":"yellow","box":[40.9,58.5,161.9,84.1],"p":284,"i":0,"sec":"abwrackwerft"},{"t":"p","x":"Manchmal ist ein hartes „SCHNITT!“ der beste Weg, ein Abenteuer zu beenden. Wenn du dich entscheidest zu spielen, was am Ende der Staffel passiert, gibt es einige Fragen zu bedenken und Punkte, auf die du zurückkommen solltest:","sz":13.0,"box":[53.9,94.3,281.8,194.3],"p":284,"i":1,"sec":"abwrackwerft"},{"t":"p","x":"• Was ist mit Payne? Hat das Team ihn geheilt, ermordet, verbannt oder anderweitig verwandelt, und wie kam es dazu? Besteht die Möglichkeit, dass er zurückkehrt oder ist seine Geschichte vorläufig abgeschlossen?","sz":9.5,"box":[53.9,207.7,279.7,267.2],"p":284,"i":2,"sec":"abwrackwerft"},{"t":"p","x":"• Wo ist der Gral? Wenn er seinen Zweck erfüllt hat, ist er in der Barmherzigkeit verschwunden, aus dem er kam? Wenn nicht, hat er vielleicht einen neuen Träger aus den Reihen der SC, der Mächtigen der Stadt oder der Nebenrollen der Serie gefunden.","sz":9.5,"box":[53.9,275.9,285.9,335.4],"p":284,"i":3,"sec":"abwrackwerft"},{"t":"p","x":"• Wie ist das Team aus der Sache herausgekommen? Leben die SC noch? Sind sie gesund, noch befreundet? Wer hat sich, als es hart auf hart kam, weggeduckt, wer hat sich gewehrt und sich der Sache mit Würde gestellt? Sind einige SC jetzt Avatare oder Schläfer:innen?","sz":9.5,"box":[53.9,344.0,276.8,416.0],"p":284,"i":4,"sec":"abwrackwerft"},{"t":"p","x":"• Wie hat sich die Stadt verändert? Ist Corbin Payne weg, sind die Menschen weniger ekelhaft und korrupt oder tragen sie immer noch ihren geheimen Schmerz? Hat der Nebel die starke Ablenkung verloren, was dazu führte, dass mehr Menschen erwachten, oder ist das Gegenteil der Fall, und die Stadt rutschte in einen niedrigeren Kreis der grauen Hölle der Torwächter:innen? Was ist mit den Schäden? Wird die Stadt aufgebaut und erholt sich, oder wird sie zum zerstörten Betondschungel?","sz":9.5,"box":[53.9,424.7,285.4,546.7],"p":284,"i":5,"sec":"abwrackwerft"},{"t":"p","x":"• Wie wirken sich die Begebenheiten auf das Gleichgewicht der Kräfte zwischen Rissen aus? Reißt ein anderer Avatar die Macht an sich? Hatte Corbin Payne eine Handhabe gegen die Avatare in der Stadt, z. B. ein Dokument mit ihren Identitäten und geheimen Schmerzen? Oder taucht Corbin Payne, wenn seine Herrschaft andauert, aus dem Schatten auf und stellt eine Streitmacht von Folterknechten auf?","sz":9.5,"box":[309.0,59.9,540.5,156.9],"p":284,"i":6,"sec":"abwrackwerft"},{"t":"p","x":"• Was ist mit den Gralsritter:innen: Krystal Knight, Armand, Vince und Rio? Hat das Team sie geheilt, ermordet oder eingekerkert? Haben sie dazu beigetragen, Corbin Payne zu Fall zu bringen, oder sind sie weiter seine Diener:innen?","sz":9.5,"box":[309.0,165.6,537.6,225.1],"p":284,"i":7,"sec":"abwrackwerft"},{"t":"p","x":"• Zu guter Letzt: Was ist mit den kleinen Leuten auf der Straße, wie den wiederkehrenden Figuren der Serie und ikonischen NSC wie Goldie, Reiko oder Das und Quinn? Wo finden sie sich nun, da sich die Stadt verändert hat, wieder?","sz":9.5,"box":[309.0,233.8,540.5,293.3],"p":284,"i":8,"sec":"abwrackwerft"}],"size":[595.276,841.89]}},"figures":[{"id":"parzival-titel","page":259,"kind":"art","title":"Parzival – Titelbild","file":"img/case10/parzival-titel.webp","box":[0,0,595,676],"after":null},{"id":"eisberg","page":262,"kind":"eisberg","title":"Der Eisberg","file":"img/case10/eisberg.webp","box":[0,20,295,770],"after":null},{"id":"zustandskarten","page":264,"kind":"handout","title":"Zustandskarten „Verwundet“","file":"img/case10/zustandskarten.webp","box":[58,34,258,284],"after":null},{"id":"corbin-payne","page":268,"kind":"art","title":"Corbin Payne","file":"img/case10/corbin-payne.webp","box":[0,0,565,795],"after":null},{"id":"zeitung-gala","page":270,"kind":"handout","title":"Zeitung: Stadt nach Schüssen auf Gala unter Schock","file":"img/case10/zeitung-gala.webp","box":[28,643,285,795],"after":null},{"id":"zeitung-willkommen","page":270,"kind":"handout","title":"Zeitung: Willkommen in Payne Town","file":"img/case10/zeitung-willkommen.webp","box":[235,560,595,795],"after":null},{"id":"galahads-dolch","page":273,"kind":"handout","title":"Relikt: Galahads Dolch","file":"img/case10/galahads-dolch.webp","box":[50,325,290,660],"after":null},{"id":"corbin-tower","page":274,"kind":"art","title":"Corbin Tower","file":"img/case10/corbin-tower.webp","box":[0,0,296,795],"after":null},{"id":"avatar-szene","page":278,"kind":"art","title":"Corbin Payne und der Turm","file":"img/case10/avatar-szene.webp","box":[0,0,595,795],"after":null},{"id":"rio-cafe","page":282,"kind":"art","title":"Parkside Cafe","file":"img/case10/rio-cafe.webp","box":[0,497,595,795],"after":null}],"eisberg":{"page":262,"fig":"eisberg","nodes":[{"label":"Nachforschungen über Corbin Payne","layer":1,"x":10.9,"y":29.5,"w":11,"h":9.5,"target":"nachforschungen-ueber-corbin-payne"},{"label":"Die erste Gralsritter:in","layer":1,"x":24.2,"y":24.4,"w":11,"h":9.5,"target":"die-erste-gralsritter-in"},{"label":"Nachforschungen über den geheimen Schmerz","layer":1,"x":38.1,"y":29.5,"w":11,"h":9.5,"target":"nachforschungen-ueber-den-geheimen-schmerz"},{"label":"Die zweite Gralsritter:in","layer":2,"x":23.3,"y":42.8,"w":11,"h":9.5,"target":"die-zweite-gralsritter-in"},{"label":"Corbin Tower","layer":2,"x":10.0,"y":47.9,"w":11,"h":9.5,"target":"akt-2"},{"label":"Angriff auf die Stadt","layer":2,"x":37.6,"y":47.9,"w":11,"h":9.5,"target":"akt-2"},{"label":"Corbin Payne höchstpersönlich","layer":2,"x":23.9,"y":52.6,"w":11,"h":9.5,"target":"corbin-payne-hoechstpersoenlich"},{"label":"Nachforschungen über den Gral","layer":2,"x":39.1,"y":57.0,"w":11,"h":9.5,"target":"nachforschungen-ueber-den-gral"},{"label":"Die dritte Gralsritter:in","layer":3,"x":23.9,"y":68.3,"w":11,"h":9.5,"target":"die-dritte-gralsritter-in"},{"label":"Parkside Café","layer":3,"x":10.6,"y":73.0,"w":11,"h":9.5,"target":"parkside-cafe"},{"label":"Was sein muss","layer":3,"x":36.1,"y":72.7,"w":11,"h":9.5,"target":"was-sein-muss"},{"label":"Die Abwrackwerft","layer":3,"x":25.0,"y":79.0,"w":11,"h":9.5,"target":"abwrackwerft"}]}};
